quests[25241] = { id = 25241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Land, Corrupted", description = "The cliff giants of Feralas are extensions of the earth itself, {name}. When nature thrives, they are benevolent protectors and peaceful guardians.\n\nBut as the forest is tainted, so too are they.\n\nIf the corruption has spread to them, they will lash out at the wildlife and their own kind, causing great destruction. You must destroy any corrupted giants you come across.", sourceObjective = "Kill 7 Corrupted Cliff Giants.", completion = "The spirits of these guardians will return in time, {name}. You've freed them to move on in nature's cycle.\n\nNow it falls to us to make sure that cycle is free of corruption and needless suffering.", sourceObjectiveStatus = "unverified-source-field" }
quests[25242] = { id = 25242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Might", progress = "You seek to continue down the path of might?", completion = "You are a true champion of our cause, {name}.  None can claim to be more dedicated to the struggle than you.\n\nIt is rumored that the minions of the Scourge fear you more than they do the Lich King himself.  You are might incarnate.\n\nAccept this humble gift as a reward for your many triumphs." }
quests[25243] = { id = 25243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She Loves Me, She Loves Me NOT!", description = "Oh, sweetie! You're never going to guess who's down in the slave pits to the north.\n\n<Sassy shakes her head sadly at you.>\n\nCandy's down there, and she's working for the Trade Prince. She dropped you like a bad habit and now she's working for the other team. but it gets worse. Since you \"dealt\" with Chip, she's dating the Trade Prince!\n\nI don't know about you, but if she were my ex, I'd rip her fickle heart right out of her chest.", sourceObjective = "Rip the Fickle Heart from out of Candy Cane's chest.", progress = "What did you decide to do, hon?", completion = "I'm sure she deserved it, {name}. She should never have betrayed you like that.\n\nIt gives me the shivers to think that she might have kissed that monster, the Trade Prince!", sourceObjectiveStatus = "unverified-source-field" }
quests[25244] = { id = 25244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Kind of Name is Candy, Anyway?", description = "Can you believe that Candy Cane! You know up until you \"dealt\" with Chip, she was dating him. Now she's going out with the Trade Prince!\n\nI just can't get over the fact that she betrayed you like that with your ex. Maybe you should head down into the Slave Pits and take care of her once and for all?", sourceObjective = "Slay Candy Cane.", progress = "Are you having second thoughts?", completion = "Serves her right for stealing your man in the first place.", sourceObjectiveStatus = "unverified-source-field" }
quests[25246] = { id = 25246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, brother." }
quests[25247] = { id = 25247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, brother." }
quests[25248] = { id = 25248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, brother." }
quests[25249] = { id = 25249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, brother." }
quests[25250] = { id = 25250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Dream", description = "It is ready. Take this, {name}; a beacon of natural essence, blessed by the will of Ysondre.\n\nTo the east, on the other side of the flowing brook, is Dream Bough. There stands the Great Tree, the tallest in Feralas, a sapling of the World Tree itself. A portal to the heart of the Emerald Dream sits in its trunk, and it is this portal you must seal.\n\nThe portal will be guarded, but you must be brave. May the Earth Mother watch over you.", sourceObjective = "Use Ysondre's Tear to seal the portal at Dream Bough.", completion = "The corruption has been stemmed! The forest can begin to heal now.\n\nMay you have the blessing of the Earth Mother wherever you go, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[25251] = { id = 25251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Confrontation", description = "{name}, this is it! Thrall's down at the Gallywix Docks fighting the Trade Prince right now!\n\nYou gotta jump into your Ultimate Footbomb Uniform and get over there!", sourceObjective = "Get into the Ultimate Footbomb Uniform and then deal with Trade Prince Gallywix.", progress = "{name}, you have to go deal with the Trade Prince before it's too late!", completion = "You did it! You did it!\n\nWe're saved, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25252] = { id = 25252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rulers of Dire Maul", description = "Now that we've put the hurt on them at the ruins, it's time to attack the ogres in their own territory.\n\nThe Gordok are the \"upper class\" of the Gordunni clan, chosen to defend Dire Maul. They'll know we mean business once we start taking out their strongest members.\n\nNothing fancy here, {name}. Just get out there and crack some Gordok skulls.", sourceObjective = "Kill 6 Gordok Enforcers and 6 Gordok Ogre-Mages.", completion = "Excellent! Even these fools will soon know that to stand against the Horde means death.", sourceObjectiveStatus = "unverified-source-field" }
quests[25255] = { id = 25255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harrying the Hunters", description = "Twilight's Hammer has revealed itself as more than a mere cult. They're a war machine - a swarm of locusts moving up the mountain, devouring anything in their way.\n\nThe parts of the forest they're not setting ablaze are being scoured of life in order to feed the mortal cultists.\n\nWe've got to put a stop to the hunters canvassing Wolf's Run, not only to preserve what wildlife remains but to force the cult to march on empty stomachs. Look south of here, as well as up the road to the east.", sourceObjective = "Kill 6 Twilight Hunters at Wolf's Run in Mount Hyjal.", progress = "How goes the fight below?", completion = "Thank you, {name}. I worry that our actions here may be too little, too late, but nature always has a way of rebuilding itself that never ceases to amaze.", sourceObjectiveStatus = "unverified-source-field" }
quests[25256] = { id = 25256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sent for Help", description = "You, {race}, stop a minute.\n\nMy boss Spiketooth sent me to look for help and supplies.  You don't appear to be a merchant, but you can probably still help him out.  He's just to the southeast of here, next to the crashed cart.  Oh, and tell him I sent you... I want to make sure that he knows I'm not just slacking off over here.", sourceObjective = "Report to Spiketooth at Deadeye Shore in Durotar.", completion = "Vek'nag sent you?  Without telling you that I need wagon wheels, nails, and rations?  That idiot.", sourceObjectiveStatus = "unverified-source-field" }
quests[25257] = { id = 25257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghislania", description = "I own a couple gladiators that I put into competitions around Kalimdor.  You can see most of them chained up around here... we were lucky to rein these ones in after the cart broke down.\n\nGhislania, that naga over there... she's lost her last three fights.  She could use a tune-up, or maybe just a little bit of thrashing.  Go challenge her, I'll bet even YOU are stronger than she is.", sourceObjective = "Defeat Ghislania in combat.", completion = "I watched you fight out there.  How long you been a {class}?\n\nYou're alright, kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[25258] = { id = 25258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Griswold Hanniston", description = "Griswold, chained up over there on the cliffs, is my newest gladiator.  We found him just south of here, sniffing around with Northwatch soldiers.  I had my men nab him up, and now he works for me.\n\nHe looks tough enough, but he hasn't really been battle-tested yet.  Go pick a fight with him so I can see if he's worth keeping around.", sourceObjective = "Defeat Griswold Hanniston in combat.", progress = "How did you do?", completion = "I'm at a crossroads now, {name}... you defeated him easily in combat, but then again, I did get him for free, and he's pretty cheap to feed.  Maybe we'll keep him around for a bit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25259] = { id = 25259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaur Icehorn", description = "I wouldn't normally keep a taunka as a captive, due to their close relationship with the Horde... but this one is a traitor, and a criminal to boot.  Exiled by his own tribe, he canoed down to Azshara and was found stealing supplies from Valormok.  He would have been put to the axe had I not been standing by, wallet in hand.\n\nGaur is my winningest gladiator, {class}.  I'll bet you 10 silver that you can't beat him.", sourceObjective = "Defeat Gaur Icehorn in combat.", completion = "Fine, here's the money... but you'd better make yourself scarce before I reconsider my policy on keeping Horde slaves.", sourceObjectiveStatus = "unverified-source-field" }
quests[25260] = { id = 25260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fizzled", description = "The flood to the southwest wiped out one of the few Burning Blade camps that still pockmark Durotar.  This one was led by a goblin named Fizzle Darkclaw, and believe me, we're better off without him.\n\nDarkclaw, however, did possess an orb that the Horde is interested in procuring.  Who knows why... I leave that to the warlocks.  All I know is that I need that orb.", sourceObjective = "Obtain Fizzle's Orb from Fizzle Darkclaw in Thunder Ridge.", progress = "Run into any trouble on the way?", completion = "I ask for an orb, and you bring half of the goblin's arm with you?  I like the way you work.\n\nTell you what... you've already given me a hand.  Allow me to return the favor.", sourceObjectiveStatus = "unverified-source-field" }
quests[25261] = { id = 25261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Margoz", description = "One of our more useful shaman, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains, just outside Orgrimmar, that shelters a large band of Burning Blade cultists.\n\nBefore you go to Skull Rock, speak with Margoz.  He is wise and his council is valued.\n\nHe is camped to the southeast, between the coast and Drygulch Ravine.\n\nFollow his advice, but whatever Margoz says, {name}, I still want you to crush those cultists!", sourceObjective = "Speak with Margoz.", completion = "Welcome, {name}.  Word reached me of your coming, and of your exploits in Durotar.\n\nYou are a {class} of growing skill and renown.\n\nStay on the pure path, and your future will be great indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[25262] = { id = 25262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skull Rock", description = "{name}.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.\n\nBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.\n\nGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.", sourceObjective = "Gather 6 Searing Collars from the cultists in Skull Rock.", progress = "Have you yet entered Skull Rock, {name}?  Do you have the Searing Collars?", completion = "Good.  Hiding within these collars is the secret behind the Burning Blade.  And I will uncover that secret...", sourceObjectiveStatus = "unverified-source-field" }
quests[25263] = { id = 25263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeru Fireblade", description = "The Searing Collars you brought me are powerful demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.\n\nTake a searing collar to Neeru Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.\n\nYou may find Neeru in Orgrimmar in the Cleft of Shadow.", sourceObjective = "Bring an Example Collar to Neeru Fireblade in Orgrimmar.", progress = "My most humble greetings, {class}.  How might I help my {race} brother today?", completion = "Ah, and where did you get this?  Good Margoz sent you to me, did he?\n\nWell, let me take a closer look...", sourceObjectiveStatus = "unverified-source-field" }
quests[25264] = { id = 25264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ak'Zeloth", description = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.\n\nIt belongs to the Burning Blade.\n\nYour role in this tale is nearly complete, {name}.  Go to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  Pass on to him this information.", sourceObjective = "Speak with Ak'Zeloth at Far Watch Post in the Northern Barrens.", completion = "This is not news to me.  While I appreciate your efforts, the Burning Blade will have to wait.  We have other matters to which we must attend.", sourceObjectiveStatus = "unverified-source-field" }
quests[25265] = { id = 25265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory!", description = "We just can't thank you enough for all that you've done. Now we can all get off of this island before it kills us!\n\nThrall is going to want to speak with you first, {name}. I'll rocket you over there.\n\nSee you on the ship!", sourceObjective = "Speak with Thrall at the Gallywix Docks on the Lost Isles.", completion = "Lok'tar! Victory, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25266] = { id = 25266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Emissary", description = "The goblins and orcs have accomplished too much together to part ways now, {class}. I intend for the Bilgewater Cartel to become part of the Horde.\n\nI have something that I want you to deliver to the new warchief. Give this package to my Kor'kron friend on the dock at Bladefist Bay in Durotar. He will help you to get into Orgrimmar safely.\n\nSpeak with Sassy Hardwrench on the ship when you are ready to set sail.\n\nUntil we meet again. Aka'Magosh, a blessing on you and yours, {name}!", sourceObjective = "Deliver the Sealed Package to the Kor'kron Loyalist on the docks at Bladefist Bay in Durotar.", progress = "What possible business could you have in Orgrimmar, {race}?", completion = "<The orc continues on in hushed tones.>\n\nI know who sent you. Did he give you something to deliver to me?", sourceObjectiveStatus = "unverified-source-field" }
quests[25267] = { id = 25267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message for Garrosh", description = "<The Kor'kron loyalist opens the package, palming one object while reading a letter from within. As he finishes the note from Thrall, the barest hint of a fanged smile appears on his face.>\n\nYou are to take this directly to Warchief Hellscream inside Orgrimmar. Make certain that Garrosh knows that it is from Thrall.\n\nTake my battleworg. Hurry, little goblin, there is no time to waste for this message!", sourceObjective = "Deliver the SI:7 Emblem to Garrosh Hellscream at Grommash Hold in Orgrimmar.", progress = "What is this, {race}? Your kind are not allowed inside Grommash Hold.\n\nLeave before I have to teach you your place.", completion = "Thrall had you deliver this?\n\n<The Warchief takes a step back, visibly shaken.>\n\nI understand the meaning of this all too well, {race}.\n\n\n\nThis smelly thing was caught unattended in the city and seems to recognize you.\n\nI have already put others of your kind to work in Azshara. Take it with you when you leave.\n\nFrom this day forward, you and your Bilgewater Cartel will serve the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[25268] = { id = 25268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice of Goldrinn", description = "Southwest of here lies the shrine of Goldrinn, a memorial erected in honor of the ancient wolf spirit and his contribution during the War of the Ancients.\n\nOur new worgen allies have been drawn to the memory of the wolf god - go figure! - and were in the process of cleaning up the shrine.\n\nI haven't heard anything from my contact, Ian Duran, in days. Can you fly down there and find him? I've got a bad feeling that Goldrinn's shrine is in trouble...", sourceObjective = "Locate Ian Duran near the Shrine of Goldrinn in Hyjal.", completion = "You're here to rescue me, {class}? Thank you!\n\nNo, no, don't worry about the cage for now. My life isn't important. We've got to save the shrine, first.", sourceObjectiveStatus = "unverified-source-field" }
quests[25269] = { id = 25269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice of Lo'Gosh", description = "Have you heard of Lo'Gosh, the wolf ancient? In the Alliance tongue, he is known as \"Goldrinn.\"\n\nI don't need to tell you how important the wolf god has been to the Horde - his tenacity under adversity has been an inspiration to all of our disparate races.\n\nSouthwest of here, down in the valley, lies a shrine to Goldrinn. My friend Takrik Ragehowl was refurbishing the shrine when I stopped hearing from him. I fear the worst.\n\nPlease find Takrik and make sure the shrine is okay!", sourceObjective = "Locate Takrik Ragehowl near the Shrine of Goldrinn in Hyjal.", completion = "Lok'tar, {class}! Don't worry about this cage - these animals will come to fear me before long.\n\nMy first priority is to clear this filth away from my beloved shrine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25270] = { id = 25270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Howling Mad", description = "The shrine has been taken, {name}. We need the tenacity of Lo'Gosh now more than ever.\n\nThese defilers - the lice-ridden wolf-men running rampant over the shrine - dishonor the memory of the wolf god. They arrived with the Twilight's Hammer, howling with their own twisted religion. They seek to corrupt noble Lo'Gosh to fit their own warped pantheon.\n\nKill them! Kill them and bring me the tools of their worship, a kind of polluted incense. I must understand what they want with the shrine...", sourceObjective = "Acquire 6 Polluted Incense.", progress = "These animals were once men, but they've turned into mindless beasts under the influence of the Twilight's hammer. Do not hesitate to slay them all.", completion = "<Takrik examines the incense.>\n\nDisgusting. This is like the incense we burn when we wish to commune with the spirits... but it's... befouled.", sourceObjectiveStatus = "unverified-source-field" }
quests[25271] = { id = 25271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldrinn's Ferocity", description = "The beasts you see here, they're no longer my brothers from Gilneas. They've been corrupted by some kind of madness, and they've taken over the shrine.\n\nThey came when the Twilight's Hammer arrived in Hyjal, and they howl the name of some blasphemous mockery of our beloved Goldrinn. Forget about me - destroy these vandals before they continue to defile the shrine.\n\nAs you destroy them, look for the incense they carry and bring me some samples.", sourceObjective = "Acquire 6 Polluted Incense.", progress = "Worgen like myself were drawn to the story of Goldrinn, his strength and wisdom. But these vandals - they worship a different aspect of the wolf god entirely.", completion = "<Ian examines the incense.>\n\nAs I suspected. These reagents bear the marks of the Twilight's Hammer. And here, the name \"Lycanthoth.\" I believe these are used in a summoning ritual...", sourceObjectiveStatus = "unverified-source-field" }
quests[25272] = { id = 25272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lycanthoth the Corruptor", description = "The actions of these feral dogs are beginning to make sense. The Twilight's Hammer fears the power of the ancients. They do not want Lo'Gosh to return.\n\nSo they've summoned their own wolf god - a perversion of what once was. \"Lycanthoth,\" the corruptor.\n\n{name}, Lycanthoth is but a shadow of Lo'Gosh's power, but the beast must be destroyed so that the true ancient can return. Take this incense, and burn it in the Maw of Lycanthoth east of here. Slay the monstrosity and free the spirit of Lo'Gosh!", sourceObjective = "Use Lycanthoth's Incense within the Maw of Lycanthoth in Hyjal to summon and kill Lycanthoth.", progress = "Your bravery is an inspiration to others, {class}. Tell me your name.", completion = "You were brave to face down Lycanthoth, {name}. Like myself, he was a primal force of nature... but his origins were from a darker place.\n\nThose who birthed that beast reached deep into the blackness, channeling powers never intended for this world.\n\nCome, {class}. Climb onto my back, and let us show these beasts the true face of ferocity!", sourceObjectiveStatus = "unverified-source-field" }
quests[25273] = { id = 25273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lycanthoth the Corruptor", description = "I think I understand what's happening here. The Twilight's Hammer fears that the ancients may someday rise up to oppose them. They'll do anything to stop the return of Goldrinn.\n\nThis \"Lycanthoth\" is a twisted version of our beloved wolf god, summoned by the Twilight's Hammer to replace him.\n\nBah! It is but a shadow of Goldrinn's power. {name}, kill this beast so that the true ancient can return. Take this incense and burn it in the Maw of Lycanthoth east of here. Slay that beast and free Goldrinn!", sourceObjective = "Use Lycanthoth's Incense within the Maw of Lycanthoth in Hyjal to summon and kill Lycanthoth.", progress = "Your bravery is an inspiration to others, {class}. Tell me your name.", completion = "You were brave to face down Lycanthoth, {name}. Like myself, he was a primal force of nature... but his origins were from a darker place.\n\nThose who birthed that beast reached deep into the blackness, channeling powers never intended for this world.\n\nCome, {class}. Climb onto my back, and let us show these beasts the true face of ferocity!", sourceObjectiveStatus = "unverified-source-field" }
quests[25274] = { id = 25274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signed in Blood", description = "You're here at last, {name}.  Just in time as well.\n\nNews of Ragnaros' emergence has spurred a large wave of recruits to seek membership in the Twilight's Hammer.\n\nIf you're to infiltrate the cult, the time is now.  We will need recruitment papers -- signed in blood by a referring Twilight member.  Lure one of the new recruits away from the group and hit them with this blackjack.\n\nIf you're lucky, you'll be able to steal his recruitment papers.  Bring them back to me and we'll do our best to alter them.", sourceObjective = "Lure a Twilight Recruit away from the group and take his Twilight Recruitment Papers.", progress = "Did you get the papers?", completion = "Excellent.  I'll do my best to alter these documents.", sourceObjectiveStatus = "unverified-source-field" }
quests[25275] = { id = 25275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Labor Captain", description = "Your people are busy with the terraforming of Azshara. We will remake the land in the image of the Horde so that all will know that Kalimdor is ours!\n\nGo north through the city. On the far side of the Valley of Honor you will find the Orgrimmar Rear Gate. Report to Labor Captain Grabbit outside the gates, goblin.\n\nFor the Horde!!!", sourceObjective = "Report to Labor Captain Grabbit at the Orgrimmar Rear Gate in Azshara.", completion = "{name}? The {name}?!\n\n\n\nThe rumors are already flying about you. I don't know if I should be thankful or frightened that you're here. At least we don't have any volcanoes in Azshara!\n\nHonestly, I can't believe you're showing your face here... Trade Prince Gallywix has setup shop atop the mountain!", sourceObjectiveStatus = "unverified-source-field" }
quests[25276] = { id = 25276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your New Identity", description = "There.  Not my best work, but certainly not my worst.  You will be known as \"{name}damus\" among the cultists.\n\nThese papers will bump you ahead of the other recruits and allow you to speak directly to the Twilight instructors.\n\nGo to the proving grounds and show these to Condenna the Pitiless.  She's separating the wheat from the chaff.\n\nShow her what you're made of.", sourceObjective = "Speak to Condenna the Pitiless at the Training Grounds in Hyjal.", progress = "You will address me with the respect I am due, recruit.", completion = "Chareondamus?  Let us hope your parents brought you into this world with more than just a ridiculous name.", sourceObjectiveStatus = "unverified-source-field" }
quests[25277] = { id = 25277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning House", description = "We are well on our way to returning the shrine to its former glory, {name}. But there is some housecleaning to take care of. On the other side of this meadow, some ogre squatters are setting up camp, led by a thick-headed chunk of ugly by the name of Gar'gol.\n\nKill Gar'gol's minions and see if we can't send him packing.", sourceObjective = "Kill any combination of 8 Hovel Brutes or Hovel Shadowcasters within Gar'gol's Hovel in Hyjal.", completion = "Hah! So you really sent some heads rolling, did you?\n\nIt was said during the War of the Ancients that Lo'Gosh fought demons for ten days solid. Hopefully you weren't fighting that long...", sourceObjectiveStatus = "unverified-source-field" }
quests[25278] = { id = 25278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning House", description = "Thanks to your efforts, we may soon be able to return this shrine to its former glory. But first we've got to secure this valley. South of here, a group of ogres led by Gar'gol has set up camp in a stinking hovel.\n\nI wouldn't characterize Gar'gol as a 'threat' so much as an enormous fleshy obstacle thrown into our path to distract us from the real danger. Nonetheless, he and his goons will have to be dealt with.\n\nKill Gar'gol's minions in Goldrinn's name!", sourceObjective = "Kill any combination of 8 Hovel Brutes or Hovel Shadowcasters within Gar'gol's Hovel in Hyjal.", completion = "You really cleared that place out, didn't you? Well done!\n\nThe night elves once told me a story about how Goldrinn fought and killed a dreadlord, even as three others clung to his flanks, burning his flesh. I wonder if you or I will ever have the strength to do the same?", sourceObjectiveStatus = "unverified-source-field" }
quests[25279] = { id = 25279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine Reclaimed", description = "Yes, {name}. I am Goldrinn, the one called \"Lo'Gosh\" in your tongue. Your persistence in the face of fear has unbound me from twilight's grasp.\n\nMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.\n\nReturn to Takrik and continue your work here in Hyjal. I will have need of you again soon.", sourceObjective = "Return to Takrik Ragehowl at the reclaimed Shrine of Goldrinn in Hyjal.", completion = "{name}, it was incredible! For a fleeting moment I saw Lo'Gosh through the trees - a creature of both fury and light. My cage collapsed and the vandals melted like wax under the kiss of his claws, their screams and howls echoing through the valley... Was that your work?", sourceObjectiveStatus = "unverified-source-field" }
quests[25280] = { id = 25280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine Reclaimed", description = "Yes {name}, I am Goldrinn. Your persistence in the face of fear has unbound me from twilight's grasp.\n\nMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.\n\nReturn to Ian and continue your work here in Hyjal. I will have need of you again soon.", sourceObjective = "Return to Ian Duran at the reclaimed Shrine of Goldrinn in Hyjal.", completion = "{name}, it was astounding! Goldrinn himself appeared to free us, his white fur bright like the summer moon. Our cages collapsed and the vandals melted like wax under the kiss of his claws. He was beautiful, {name}. Beautiful!", sourceObjectiveStatus = "unverified-source-field" }
quests[25281] = { id = 25281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pay It Forward", description = "You are now able to move about this realm more freely and without fear of drowning.\n\nThis is where our work begins.\n\nFirst, you have many allies nearby who are drowning as we speak. As I saved you, you must save them.\n\nI have enchanted the shell you brought me. Use it to rescue your friends.\n\nHurry now!", sourceObjective = "Use the Enchanted Conch Shell to rescue 6 Drowning Soldiers.", progress = "Were you able to rescue the soldiers, {race}?\n\nWe will perish without their help...", completion = "While you were away, I was able to revive some of the fallen soldiers.\n\nWe'll need every hand if we are to survive here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25283] = { id = 25283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepping the Speech", description = "High Tinker Mekkatorque asked me to write a speech that he could give before the battle starts, but I can't tell which draft is good and which ones just stink.\n\nCould you try some of them out on some of the local gnome residents?  This device creates an image of Mekkatorque saying a few lines from each of my speech drafts.\n\nLet me know which one works, okay?", sourceObjective = "Use the Gnomish Playback Device in front of Ozzie Togglevolt north of Kharanos, Milli Featherwhistle at Steelgrill Depot and Tog Rustsprocket outside the Kharanos Inn. Return to Toby Ziegear when all the speeches have been given.", progress = "Hey, did you have a chance to test out my speeches?", completion = "Oh my.  Their reactions were that different?\n\nNot completely what I was expecting, but I think I have a speech that will do.\n\nJust let me find where I put it...", sourceObjectiveStatus = "unverified-source-field" }
quests[25284] = { id = 25284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Fear", description = "Our resources are limited, {class}, but that doesn't mean we can't make some trouble down below. Use the ropes here to sneak down the hillside, then slay the human prison wardens.\n\nKilling a couple scrawny guards won't turn the tide of battle, but  imagine the fear and chaos we'll reap as the humans discover the mutilated bodies...\n\n<Holgom grins a yellowed grin, his eyes glinting.>", sourceObjective = "Kill 5 Tower Wardens. Use the ropes beside Holgom to quickly move in and out of Honor's Stand.", completion = "Good, good. It'll take them many sleepless nights to figure out where we came from and where we disappeared to after the kills...", sourceObjectiveStatus = "unverified-source-field" }
quests[25285] = { id = 25285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In and Out", description = "We've gotta get these new mechano-tanks ready for the assault.  You ready to help test these bad boys out?!  Of course you are!\n\nFirst, we need to make sure that once you're in, you can get out.  In battle, if you think your tank is going to explode, get out!  I've seen many a gnome stay in 'til the bitter end... the tank blows up, and them along with it.\n\nWell, I've upgraded this tank with an ejection seat.  Try it out for me, will ya?", sourceObjective = "Test out the ejection system in the Ejector Mechano-Tank.", progress = "Those ejection systems aren't going to test themselves... though that isn't a bad idea...", completion = "Hey, look at that!  You weren't blown to bits!", sourceObjectiveStatus = "unverified-source-field" }
quests[25286] = { id = 25286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words for Delivery", description = "Here we go.  This is the speech, {name}!\n\nIt has everything to be a great battle starter: It's inspirational, has eloquent language and speaks directly to gnomes.  Never has a finer speech been written!\n\nTurn this in to Captain Tread Sparknozzle and get some transportation to High Tinker Mekkatorque!", sourceObjective = "Give the speech to Captain Tread Sparknozzle at Steelgrill Depot.\n\nProvided item:", completion = "Toby is all done with the speech?  Let me see...\n\n<Reads the speech> Pumping pistons! What a fantastic speech! I knew Toby was a good writer, but this is perhaps the best he's ever written.\n\nI think it's time to get you out to the battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[25287] = { id = 25287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words for Delivery", description = "All right, soldier. Time to prove your worth!\n\nTake the speech and board the flying machine \"Thunderflash\".  It's the fastest ship to High Tinker Mekkatorque and this speech is the only thing he's waiting on before starting Operation: Gnomeregan.\n\nGo! Now!", sourceObjective = "Ride 'Thunderflash' from Steelgrill Depot to High Tinker Mekkatorque and deliver Toby's speech.", progress = "Were you here to deliver Toby Zeigear's speech?", completion = "This is the final draft, then?  Let me have a look...", sourceObjectiveStatus = "unverified-source-field" }
quests[25289] = { id = 25289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Step Forward...", description = "With the ejection system working, I think we're ready to test out movement.  This tank has an extra special feature: Automatic Evasive Maneuvers!\n\nI want you to check out the servos on the left leg, the right leg and the Automatic Evasive Maneuver system.\n\nThis is easy stuff, so it shouldn't take too long.", sourceObjective = "Test the Scuttling Mechano-Tank's maneuverability.", progress = "I'm waiting on those test results, {name}.", completion = "Hmm... so the left leg servo was activating the right leg?  But I saw the left leg moving...\n\nEh, details.  I'll get to that later, but two out of three things worked: That isn't half bad!\n\nThanks for checking this out for me, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25291] = { id = 25291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Training", description = "You've proven you're worthy of at least participating in our most basic training.\n\nYou'll find one of our settlements east of here.  Speak to instructor Mylva there.", sourceObjective = "Speak to Instructor Mylva in Hyjal.", completion = "You think you're ready for the next step then, Chareondamus?\n\nLet's see what you're capable of.", sourceObjectiveStatus = "unverified-source-field" }
quests[25292] = { id = 25292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Next of Kin", description = "<Nato pulls you aside and speaks in a whisper.>\n\n{name}, I have removed the bullet from Gann's chest, but the bubbles in his blood tell me all I need to know. His lungs are punctured, and the wound grows septic. He is not long for this world.\n\nTake this. It's the bullet that killed him. His family will want to know what became of their youngest warrior.\n\nSeek out Alto Stonespire. He is posted in Dustwallow Marsh. Go northeast, and follow the roads to Brackenwall Village.", sourceObjective = "Take the Dwarven Slug to Alto Stonespire at Brackenwall Village in Dustwallow Marsh.", progress = "Hello, {class}. You look to be caked in dust instead of mud. I take it you've ventured here from the Barrens?", completion = "<Alto clenches the bullet in his palm as you tell your story.>\n\nGann? Dead? I ... I should've known. His temper... his recklessness. I knew someday it would get the better of him.\n\nBut it sounds as though you've already gifted him with vengeance. Thank you, {name}!\n\nTurn your attention now to Dustwallow. If the Alliance finishes their cursed road through here, all your victories in the Barrens may have been for nothing.", sourceObjectiveStatus = "unverified-source-field" }
quests[25294] = { id = 25294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walking the Dog", description = "Hmmmphh.... it seems they'll let anyone in these days.\n\nVery well.  You doubtlessly became acquainted with Smolderos in the proving grounds.\n\nWell, I've been entrusted with the care of one of his pups.  Quite the little terror -- if he grows up to be anything like his father he shall serve our cause well.\n\nCollect meat from the basilisks around the area and feed them to him.", sourceObjective = "Collect and feed 5 pieces of Charred Basilisk Meat to the Spawn of Smolderos.", progress = "Well... is he fed?  I'm not taking him back unless the little monster's not hungry anymore.", completion = "Excellent.  This little pup will grow to be strong and merciless like his father.", sourceObjectiveStatus = "unverified-source-field" }
quests[25295] = { id = 25295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Press Fire", description = "Safety systems, online!  Motor functions, functioning!  Now all we need is to make sure that the guns will fire.\n\nThis shouldn't be too hard, {name}.  The mechano-tank on the hill behind us has been loaded with harmless pellets. Just fire off a couple rounds at the nearby targets and report back to me.", sourceObjective = "Test out the Shooting Mechano-Tank weapon systems on the nearby targets.", progress = "What's wrong?  Did you forget how to shoot?", completion = "Hmm... so the bullets had quite a bit of spread?\n\nTo some people that may be a problem... me, though, I see it as a blessing in disguise!\n\nOur enemies will be running all over the place, so with a bit of a spread, the tank drivers won't need to lead the target!", sourceObjectiveStatus = "unverified-source-field" }
quests[25296] = { id = 25296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather the Intelligence", description = "It's me, {name}, Ortell!\n\nDon't look directly at the outhouse... you'll give away my position.\n\nEverything's going according to plan then?  Excellent!\n\nI'm going to need you to obtain some intelligence while you're here.  It might not seem like much to get our hands on a map or a letter, but it may mean saving a hundred lives on our side if we can anticipate our enemy's next move.", sourceObjective = "Obtain the Twilight Communique and the Hyjal Battleplans.", progress = "Did you get the documents, {name}?", completion = "Excellent job, {name}.  Or should I say: \"{name}\"damus?\n\nGive me a minute to read these.", sourceObjectiveStatus = "unverified-source-field" }
quests[25297] = { id = 25297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Mouth of Madness", description = "I know of a draught that should jolt these gibbering former slaves back to reality. Gather some stonebloom from the rocks around Gar'gol's hovel, some bitterblossom from the shores of the nearby lake, and a darkflame ember from one of the braziers at the hovel entrance. The draught won't last long, so combine the ingredients at a twilight cauldron by the entrance to the hovel.\n\nOne sip of that draught should knock some sense into the brainwashed slaves!", sourceObjective = "Gather up Stonebloom, Bitterblossom, and a Darkflame Ember.", progress = "<The cauldron burbles, filled with a disgusting liquid.>", completion = "<You dump out the current contents of the cauldron, instantly killing the surrounding plant life.>\n\n<The draught you brew in its place boils chunky and reeks of rotted cabbage. You turn your head aside and bottle it up.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25298] = { id = 25298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Your Mind, the Rest Follows", description = "<Rio said that the draught would not remain effective for long.>\n\n<You'd better hurry into the hovel and administer it to as many Twilight Servitors as you can find.>", sourceObjective = "Speak with 8 Twilight Servitors to administer the draught and rescue them.", progress = "Did the draught work?", completion = "Excellent! Let's hope the damage wasn't permanent.\n\nJudging by the poor victims still in camp here, the Twilight's Hammer really messed with their heads.", sourceObjectiveStatus = "unverified-source-field" }
quests[25299] = { id = 25299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mental Training: Speaking the Truth to Power", description = "You might think you're ready to receive the knowledge we're to impart on you.  But you are not.\n\nThink of your mind as a box inside a series of other boxes.\n\nEach step of our training will open one of those boxes, until you are ready to achieve direct communion with the elements.\n\nTake the Core of Ascension and answer all questions it asks of you, truthfully.  Failing to do so could be... fatal.", sourceObjective = "Use the Orb of Ascension and answer 10 answers correctly.", progress = "You've returned.", completion = "You've succeeded, Johnfdkdamus.  You're ready for the next step.", sourceObjectiveStatus = "unverified-source-field" }
quests[25300] = { id = 25300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Twilight", description = "The ogre clan across the lake is led by Gar'gol. I use the term loosely; Gar'gol has the intelligence of raw beef.\n\nSo far as I can tell, Gar'gol is taking orders from a magical instrument: \"The Eye of Twilight.\" He follows its commands unquestioningly.\n\nIf we can sabotage the eye, we can cause unimaginable havoc.\n\nGo to Gar'gol's hovel and seek out the Eye of Twilight near the entrance. Study it. Find a way to subvert it. Ah, marvelous chaos...", sourceObjective = "Seek out the Eye of Twilight near the entrance to Gar'gol's Hovel in Hyjal.", completion = "<You approach the Eye of Twilight. As your fingertips graze its luminescent surface, you are aware of a malignant presence peering back at you, searching your soul.>\n\n<Instinctively, you draw back.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25301] = { id = 25301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering Puppets", description = "<During your brief communion with the Eye, you felt that its power source lay deep within the hovel. You felt the weight of a powerful tome, binding together four elements.>\n\n<Mastering the Eye will require you to search the hovel for this tome.>", sourceObjective = "Locate the Twilight Apocrypha inside of Gar'gol's Hovel in Hyjal.", completion = "<A heavy tome, bound in flesh, lies open on the table.>\n\n<The language - pictographic and scrawled in rust-colored ink - is undecipherable, but notes and translations are tucked within several pages. This must be what you're looking for.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25303] = { id = 25303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementary!", description = "<You can't read the text, but diagrams seem to indicate that the devices around you should be activated in a set order.>\n\n<One passage of the Apocrypha has been translated to modern text:>\n\n   In the beginning was shadow eternal.\n   Hate blazed forth, and FIRE was born.\n   Wounds scabbed, and so begat EARTH.\n   Cries of anguish birthed howling WIND.\n   Wherein the skies wept seas of TEARS.\n      We live in the shadow,\n      The world we know\n   Built of rage, hurt, anguish and sorrow.", sourceObjective = "Activate the four nearby elemental crucibles in the correct order to take control of the Eye of Twilight.", progress = "<You pour over the Apocrypha, trying to make sense of it all.>", completion = "<Flush with the energies of the captured elementals, you stand before the Twilight Apocrypha. The pages turn of their own accord.>\n\n<Suddenly, you see what the Eye sees. It is yours to command!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25304] = { id = 25304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Sardor", description = "Our settlement on Sardor Isle was lost to the Hatecrest naga. Overwhelmed by their numbers, we fell back to the mainland. While they coveted their newly-gained sandbar, we raised New Feathermoon on the shore and amassed an even greater army.\n\nNow, the Hatecrest will be driven back into the sea. Find our Ancient of War along the shore. He will take you to the front lines, where Tambre leads the offensive.", sourceObjective = "Speak with Tambre on Sardor Isle.", completion = "These foul things will be driven back into the sea. I hope you're ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[25305] = { id = 25305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Look Back", description = "Our settlement on Sardor Isle was lost to the Hatecrest naga. Overwhelmed by their numbers, we fell back to the mainland. While they coveted their newly-gained sandbar, we raised New Feathermoon on the shore and amassed an even greater army.\n\nNow, the Hatecrest will be driven back into the sea. Speak with Sentinel Ranadae to join our forces at Sardor. Slay the naga, and make sure whichever foul snake they take orders from is killed as well.", sourceObjective = "Kill 10 Hatecrest Naga and slay their leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[25306] = { id = 25306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're In The Army Gnow!" }
quests[25308] = { id = 25308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of Discord", description = "According to the intelligence you acquired, there is major friction between the ogres and non-ogres in the cult.\n\nHigh Cultist Azennios and the ogre mage Karr'gonn are meeting at the Seat of the Chosen in an attempt to ease the conflict.\n\nThere is an outhouse like this one at the Seat of the Chosen.  Go there and put on this ogre disguise.  Find a way to kill Azennios while he's in this mission of peace.\n\nWe must exploit this division as much as we can!", sourceObjective = "Distract Karr'gonn and slay Dark Cultist Azennios at the Seat of the Chosen in Hyjal.", progress = "Is it done yet, {name}?", completion = "Excellent job, {name}!  You've outdone yourself this time.", sourceObjectiveStatus = "unverified-source-field" }
quests[25309] = { id = 25309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritual Training: Mercy is for the Weak", description = "You've made it this far.  Others haven't.\n\nGo to Doom's  Vigil, just north of here.  We've rounded up all the... failures.  I want you to help take care of them.  It'll be good for your spiritual growth.\n\nIf this cold-blooded act gives you trouble, think of it as their second chance.  Should any of them manage to kill you... well, they'll take your spot.", sourceObjective = "Slay 5 Failed Supplicants at Doom's Vigil.", progress = "Well, Hidemyaxedamus.  Is it done?", completion = "You're on the fast-track to success.  Let us hope you don't ruin your track record with such silly notions as compassion and humaneness.\n\nCome, then.  Let us discuss your future.", sourceObjectiveStatus = "unverified-source-field" }
quests[25310] = { id = 25310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greater of Two Evils", description = "We took Darkwhisper Gorge from the demons of the Burning Legion by force.  We've held on to our territory pretty well so far, with one exception.\n\nWe recently lost the Gates of Sothann to a pit lord and his army.  We cannot allow this to stand.\n\nUse this talisman when you're near him.  You'll gain the powers of a flame ascendant temporarily.  Make it count.", sourceObjective = "Use the Talisman of Flame Ascendancy and slay Garnoth, Fist of the Legion, at the Gates of Sothann in Hyjal.", completion = "Excellent work, Beefshammichdamus.  We must show all would-be competitors that we are not ones to give up easily.", sourceObjectiveStatus = "unverified-source-field" }
quests[25311] = { id = 25311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Territory", description = "The demons of the Burning Legion think they can just walk up here and take whatever territory they want.  Sure -- the territory was previously theirs, but that's beside the point.\n\nWe'll teach them not to cross the Twilight's Hammer.\n\nHead to the Gates of Sothann and wipe out the contingent of Horrorguards that roam the area.", sourceObjective = "Slay 10 Horrorguards at the Gates of Sothann in Hyjal.", completion = "Sharp as always.  You do not disappoint me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25312] = { id = 25312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Duskwhisper", description = "<You force your own image into the Eye, manipulating it to give the ogres different orders. As you do so, you feel another presence within the Eye, probing you, seeking out a weakness. A distant being fumes with rage. You've made some enemies today!>\n\n<Your work here is done, and the ogres will be friendly to you. Return to Royce Duskwhisper at the Shrine of Goldrinn and let him know what you've accomplished.>", sourceObjective = "Return to Royce Duskwhisper at the Shrine of Goldrinn in Hyjal.", completion = "Hello, yes? What? You? Oh, you're one of the ones I sent after the Eye of Twilight, aren't you?\n\nGood work, very good. I suppose that's a valuable lesson:\n\nNever to take orders from a big purple ball.", sourceObjectiveStatus = "unverified-source-field" }
quests[25314] = { id = 25314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speech Writing for Dummies", description = "Listen, {name}.  I found out what they're doing with Jarod Shadowsong.  He's scheduled to be sacrificed by the ogres of the Twilight's Hammer as part of this year's initiation.\n\nI heard that the initiate charged with delivering the speech ahead of the sacrifice is an ogre named Okrog, but get this: you were a close second.\n\nWe need you to deliver that speech if we're to free Jarod.  Don't worry -- I'll write you some cue cards -- just make sure Okrog has an \"accident\" as he leaves the Seat of the Chosen.", sourceObjective = "Kill Okrog outside the Seat of the Chosen in Hyjal.", progress = "Well, {name}?", completion = "Excellent work, {name}.  Our plan's almost come together.", sourceObjectiveStatus = "unverified-source-field" }
quests[25315] = { id = 25315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graduation Speech", description = "You're finally ready, {name}damus.\n\nI am so proud of you and all you've accomplished.\n\nToday you will deliver a speech in front of your peers and inspire them to crush our enemies until Hyjal is nothing but a pile of ash.\n\nRemember, {name}damus.  It'll be important to read your audience's emotions and use words that best address those emotions.", sourceObjective = "Use the Initiation Podium at Doom's Vigil to successfully deliver the Graduation Speech.", progress = "Have you come to finish me off?\n\nNo... you appear to be... sane.", completion = "You.  You're clearly not with them.\n\nAn ally then?", sourceObjectiveStatus = "unverified-source-field" }
quests[25316] = { id = 25316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As Hyjal Burns", description = "{name}!  We've heard much about you and your previous accomplishments.\n\nIt is good that you've come here just as Azeroth finds itself in a time of great need.\n\nDeathwing's minions are attacking Hyjal and seek to bring the destructive Ragnaros back into our world.\n\nAronus will take you to join Malfurion's forces in Hyjal. Lend them what help you can.", sourceObjective = "Fly to Hyjal using Aronus and speak to Ysera once you're there.", completion = "<Ysera appears to be in some sort of trance.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25317] = { id = 25317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protect the World Tree", description = "<Ysera's eyes look distant, as if not fully acknowledging you.>\n\nI feel it as well, {class}. Ragnaros has arrived.\n\nWe must defeat his minions before he can join them and lend them his strength.\n\nSeek Malfurion Stormrage at the Tranquil Grove, west of here, and aid his forces in any way you can.\n\nI must seek answers from within the Emerald Dream.  You must protect the World Tree until I return.", sourceObjective = "Speak to Malfurion Stormrage at the Tranquil Grove in Mount Hyjal.", completion = "You've arrived just in time, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25319] = { id = 25319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Twilight's Hammer", description = "Make no mistake about this, {name}.  The outcome of this war will determine the very survival of our world as we know it.\n\nThe Twilight's Hammer has become more powerful than ever with Deathwing's return.  Should they succeed in taking over the World Tree, they might strike a blow from which we will never recover.\n\nIt is time we beat back the enemy.  It is time we crushed the Twilight's Hammer.", sourceObjective = "Kill 4 Twilight Flamecallers and 10 Twilight Vanquishers.", progress = "Is it done, {name}?", completion = "You've done well, {name}.  But I fear the battle is far from over.", sourceObjectiveStatus = "unverified-source-field" }
quests[25320] = { id = 25320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Scout", description = "I've heard about you, {name}, and the news you brought from the south.  The battle has reached a stalemate.\n\nOne that I fear is about to be broken by the Firelord's reawakening.\n\nThat is unless we tip the scales in our favor in some way.\n\nThere is a scout that was captured by the Twilight's Hammer.  I believe she was in possession of valuable intelligence. Find her in the Twilight camp to the west.", sourceObjective = "Find Scout Larandia at the Twilight Command Post in Mount Hyjal.", completion = "Help has arrived at last!", sourceObjectiveStatus = "unverified-source-field" }
quests[25321] = { id = 25321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Captivity", description = "I'd been scouting behind enemy lines for nearly a day when they caught me.\n\nThis attack on our frontlines is not what it appears, {name}.\n\nI'll give you all the details, but first let's find a way to get me out of here.\n\nOnly the overseers carry keys to these cages.\n\nFrom what I recall, they're in the middle of the crater, in the thick of it.\n\nSee if you can get a key off of one of them.", sourceObjective = "Obtain a Twilight Overseer's Key at the Twilight Command Post in Hyjal.", progress = "The key, {name}.  Did you get it?", completion = "I am thankful, {name}.  I will deliver my findings to our people.", sourceObjectiveStatus = "unverified-source-field" }
quests[25323] = { id = 25323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flamebreaker", description = "The large elementals that besiege us are not a singular entity.\n\nThey are an amalgamation of lesser spirits bound together by the Twilight's Hammer cultists' magic.\n\nThe rebuilt flameseer's staff will give us enough power to shatter its bonds.\n\nDestroy the smaller elementals once you've broken up the more dangerous large ones.", sourceObjective = "Kill 30 Unbound Flame Spirits.", progress = "Is it done, {name}?", completion = "Well done, {name}.  This will help us turn the tide against the enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[25324] = { id = 25324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Prisoner of Interest", description = "The Twilight's Hammer wants to free Fandral Staghelm?\n\nMalfurion suspected his corruption ran deep... this just cements it.\n\nAt any rate we cannot allow our enemies to get their hands on such a powerful arch druid.\n\nI've a plan, {name}.  We will move the prisoner through the Emerald Dream.  It will be risky, but with all the cultists present here it might be the only way to guarantee our success.\n\nSpeak to Saynna Stormrunner inside the Barrow Dens to the northeast.", sourceObjective = "Speak to Captain Saynna Stormrunner at the Barrow Dens in Hyjal.", completion = "The dragon might be right.  The Twilight's Hammer has breached our security and this is our most dangerous prisoner.", sourceObjectiveStatus = "unverified-source-field" }
quests[25325] = { id = 25325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Dream", description = "Alysra's plan might be necessary, {name}.  I don't know how much longer we can hold off the cultists.\n\nFandral Staghelm is bound by powerful spells.  He won't be able to escape you, even inside the Emerald Dream.\n\nBeware, though, for all we know the nightmare has spread to this part of the world inside the dream.\n\nTake Fandral to the surface and hand him to Alysra.  Let us hope he's more secure in Moonglade than he is here.", sourceObjective = "Deliver Arch Druid Fandral Staghelm to Alysra at the entrance of the Barrow Dens in Hyjal.", progress = "Is Staghelm with you, {name}?", completion = "You did well, {name}.  I will take Fandral to Moonglade myself.\n\nHis prison will be far enough from the battlefront there.", sourceObjectiveStatus = "unverified-source-field" }
quests[25328] = { id = 25328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar'gol's Gotta Go", description = "<Kristoff cranes his neck, trying to look you in the eye.>\n\nListen, you gotta get me outta here. They're either going to eat me or turn me over to the Twilight's Hammer. Maybe both.\n\nThey've padlocked me in, and Gar'gol keeps the key in his personal treasure chest. Kill Gar'gol if you have to - but get that key!\n\n<Kristoff flails his limbs, helplessly.>", sourceObjective = "Get the Rusted Skull Key from Gar'gol's Personal Treasure Chest.", progress = "Key? Now? Please?", completion = "<Kristoff reaches down to snatch the key.>\n\nIt's about time!\n\n<He squirms in his bonds, trying to reach the padlock behind his back.>\n\n...Can I get a little help here?", sourceObjectiveStatus = "unverified-source-field" }
quests[25329] = { id = 25329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Stonemaul", description = "So the Twilight's Hammer thinks it can just raise its own army of ogres here? In the middle of Horde territory? \n\nWe'll see about that.\n\nOgres only respect one thing: strength. I want you to lead the assault on Cho'gall's sermon, {name}. Throw wide the doors of Dire Maul, leap into the arena, and cut down his attendants.", sourceObjective = "Disrupt Cho'Gall's Twilight Sermon.", completion = "We've done it! Cho'gall himself has been utterly humiliated by you. His minions are dead, the Gordok are scattered, and now all will know the might of the Horde! Lok'tar, {name}. You've more than earned your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[25330] = { id = 25330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waste of Flesh", description = "Look at these fools.  Half of them won't even make it past this trial.\n\nThey are not worthy of ascending into our inner circles.  But perhaps... perhaps they are worthy of menial service.\n\nTake this gem and utilize its power to save some of the less competent supplicants.  Those who have no chance of succeeding.  Those already on fire, preferably.", sourceObjective = "Use the Frostgale Crystal to extinguish the flames on 4 Immolated Supplicants.", progress = "Did you find suitable servants for me, Farspaladamus?", completion = "Excellent work, Chareondamus.  I'm having the servants you chose for me briefed on their new duties.", sourceObjectiveStatus = "unverified-source-field" }
quests[25332] = { id = 25332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Me Outta Here!", description = "<You reach up to unfasten Kristoff's bonds.>\n\nGood! Make a break for the exit, and I'll follow.\n\nIf we get separated, check back here to make sure I haven't been recaptured.", sourceObjective = "Escort Kristoff out of Gar'gol's Hovel.", completion = "Kristoff, Kristoff... Oh yes, I remember now. I recall sending him on what amounted to a suicide mission.\n\nHe survived? I suppose that means he failed.\n\nStill, you deserve at least some coin for the trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[25333] = { id = 25333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Sentinels", description = "The Twilight's Hammer? Here?\n\nThis is far more serious than I expected. We've got to put a stop to this. I don't know if I'm ready to lead such an offensive, but I'm not about to let my fears get in the way of what needs to be done!\n\nI will rally our forces from Feathermoon Stronghold. Head to Dire Maul, make your way to the arena, and disrupt Cho'gall's activities; we will launch our attack during the confusion.", sourceObjective = "Disrupt Cho'Gall's Twilight Sermon.", completion = "Welcome back from the battle! The Twilight's Hammer have been disgraced in the eyes of the Gordunni, and driven from Feralas.\n\nWe've shown the glory of the Alliance in full force today! Be proud!", sourceObjectiveStatus = "unverified-source-field" }
quests[25334] = { id = 25334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Looming Threat", description = "Can ya feel how angry the elements be? They be wantin' to attack us and consume us even as we just arrive. We need ta calm dem, but that kinda wisdom only comes from knowin' what's riling them up in da first place.\n\nCome sit with me by da fire. Let yaself get lost in da flames... let ya spirit peer into the true threat.", sourceObjective = "Speak to Farseer Gadra to enter your Spirit Trance.", progress = "Lose yaself in the dancin' flames. Come with me, deeper into Vashj'ir, so that we be knowin' the face of our enemy.", completion = "We'd all suspected da naga, but I knew nothin' of the Twilight Cult bein' beneath the waves. Somehow dey are corruptin' and pervertin' the elements, makin' demselves into dese horrors.\n\nWe goin' ta have to be fightin' both of dese threats to stand a chance of bringin' peace ta Vashj'ir. We don't have da men ta do that yet.\n\nCome, {class}, we got much ta do.", sourceObjectiveStatus = "unverified-source-field" }
quests[25336] = { id = 25336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Vessel", description = "Master Uzer'i's taught me in the ways of making spirit weapons of great power. I'll help you set on the path to make some, and you'll give me the chance to practice my craft.\n\nThis vessel can shrink and trap a defeated creature inside of it. We'll need the muisek of beasts first; ironfur bears and longtooth wolves. Kill them, and use the muisek vessel to shrink and capture them before their spirits can escape.", sourceObjective = "Kill 10 Ironfur Bears or Longtooth Runners, and use the Beast Muisek Vessel to shrink and capture the fallen beasts.", progress = "Did you get the beast muisek?", completion = "As my master told me...\n\nUpon a violent death, the muisek of a creature may escape and seek revenge. Shrinking the creatures, as you did, {name}, prevents the muisek from escaping. Now we may use it as we please!", sourceObjectiveStatus = "unverified-source-field" }
quests[25337] = { id = 25337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippogryph Muisek", description = "The next step is hippogryphs.\n\nAs Master Uzer'i always said, hippogryphs have been loyal companions to the night elves for many years, an' their spirits are loyal and steadfast.\n\nI don't think they'll miss a few, and I don't care if they do. We need the muisek of 10 frayfeather hippogyphs in the wilderness to the south.", sourceObjective = "Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.", progress = "Were you able to capture the hippogryphs?", completion = "Master always said \"after killing an animal, if we allowed the muisek to escape, it may take the form of an even greater creature.\" This is dangerous stuff. Thanks for helping me with my studies.", sourceObjectiveStatus = "unverified-source-field" }
quests[25338] = { id = 25338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treant Muisek", description = "The wandering forest walkers that can be found meandering through the forest are our next target, {name}. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.\n\nSoon we will be able to use this power for our own benefit.\n\nFind three wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.", sourceObjective = "Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.", progress = "Were you able to capture the wandering forest walkers?", completion = "Thank you, {name}. This is my first time working with treant muisek...", sourceObjectiveStatus = "unverified-source-field" }
quests[25339] = { id = 25339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance on the Northspring", description = "In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...\n\nI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.\n\nEven now, I can still hear their cries echoing...\n\nI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.\n\nThe Northspring harpies can be found to the west of here. {name}, get my revenge.", sourceObjective = "Kill 6 Northspring Harpies and 6 Northspring Windcallers.", completion = "Thank you, {name}. You have put an old tauren's mind at peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[25340] = { id = 25340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Heart", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.\n\nI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.\n\nImagine her surprise when it is not her kin calling her, but her death.", sourceObjective = "Slay Edana Hatetalon and obtain Edana's Dark Heart.", progress = "The hate that Edana spreads across the land must be stopped.", completion = "Now I know that Edana is truly dead. This heart, I will keep it in memory of what you did here for me, {name}. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25341] = { id = 25341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Orb", description = "While you're down there cracking skulls...\n\nI've gotten reports that make me think these ogres may be more than the usual lumbering threat. The Warlocks among them have been seen carrying orbs, possibly items of empowerment.\n\nIt would be easy to dismiss them as crude trinkets, but I need to make sure we're not surprised. Bring me back one of these orbs.", sourceObjective = "Collect a Gordunni Orb from a Gordunni Warlock.", progress = "Do you have the orb?", completion = "Well done. Let me have a look at this.", sourceObjectiveStatus = "unverified-source-field" }
quests[25342] = { id = 25342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talk to Swar'jan", description = "We're lucky and unlucky here, grunt. Lucky that I had you bother to bring this back, and unlucky that my suspicions turned out to hold water. This thing's full of corrupted stench.\n\nIt's far too new to be something fished out of the ruins, either. Someone is supplying these ogres, and we need to know who before this becomes a situation.\n\nGet that filthy thing upstairs to Swar'jan, the warlock on top of the guard tower. He's good for a few ideas; I'd listen to his suggestions, if I were you.", sourceObjective = "Deliver the Gordunni Orb to Swar'jan in Stonemaul Hold.", progress = "Yes?", completion = "What've you got for me here? You said the Gordunni had this?\n\nDisgusting...", sourceObjectiveStatus = "unverified-source-field" }
quests[25344] = { id = 25344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Abduction", description = "There's no way the Gordunni made these. They're being supplied. Someone is giving them gifts of power, and we need to find out who.\n\nThe upper-class Gordok that guard Dire Maul will know more about this. Orhan is no doubt having you thin their numbers, but I'll need one alive.\n\nTake the orb back. It's similar to a Soulstone, so I've made some...adjustments. Hold it up in front of a weakened Gordok ogre, and once you've captured him, bring it back here.", sourceObjective = "Use the Modified Soulstone to capture a Gordok ogre.", progress = "Well?", completion = "Ahh, I can feel the whelp in there. Let's get him out and ask him some questions...", sourceObjectiveStatus = "unverified-source-field" }
quests[25345] = { id = 25345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faerie Dragon Muisek", description = "{name}, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.\n\nHere is the muisek, {name}. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.", sourceObjective = "Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons.", progress = "Were you able to capture the muisek of the faerie dragons?", completion = "Thank you, {name}. Now the spiritual powers of the faerie dragon will be available to us.\n\nI hope you willing to perform another task for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25346] = { id = 25346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mountain Giant Muisek", description = "The mountain giants left the mountains to aid the night elves when the Burning Legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.\n\nI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek.", sourceObjective = "Kill 7 Mountain Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants.", progress = "Were you able to capture the mountain giants?", completion = "Just imagine the possibilities of what we now possess, {name}. Along with the materials that you have collected, I will be able to forever trap the muisek of these creatures into whatever I wish.", sourceObjectiveStatus = "unverified-source-field" }
quests[25349] = { id = 25349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Sisters", description = "I have heard of your battle against the corrupted dragons, {name}, and I thank you for your courage... but I have disturbing news.\n\nThe dryads of the forest, though allies of the Night Elves, have always passed us by in peace. But they have become cruel and twisted, attacking any who wander the eastern wilds.\n\nI fear for the safety of the refugees here, {name}. Please, put a stop to these twisted dryads.", sourceObjective = "Kill 7 Corrupted Dryads.", completion = "I thank you, {name}, but the tale of your hunt troubles me. There should not be so many.\n\nThe sickness is still spreading...", sourceObjectiveStatus = "unverified-source-field" }
quests[25350] = { id = 25350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Apprentice", description = "If you have a moment, {class}...\n\nOne of the students I was teaching has gone to explore the darkmist ruins to the south by himself. I warned him that it was too dangerous, but he was too excited to listen.  I had spoken with him earlier about an amulet that is concealed within those ruins.  Now, I fear that he may have run off in search of it, because of me...\n\nEstulan has forbidden us to pursue him. If you go there, could you please look for him?", sourceObjective = "Look for the Lost Apprentice in the Darkmist Ruins.", completion = "<The apprentice's body is cold. He has been dead for a while.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25352] = { id = 25352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweeping the Shelf", description = "Wonderful work in the hovel, {name}. I prayed at the shrine while you were away, and in my visions, Goldrinn was watching you closely.\n\nBut we've been on the defensive too long: it's time to foil the Twilight's Hammer directly.\n\nFly up to the Lightning Ledge and disrupt their operation. Kill the stormcallers and the monstrosities they're preparing to unleash!", sourceObjective = "Slay 8 Twilight Stormcallers and 5 Howling Riftdwellers.", completion = "You should've seen the battle from here! Bodies were falling off of the cliff! Spectacular!", sourceObjectiveStatus = "unverified-source-field" }
quests[25353] = { id = 25353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning in a Bottle", description = "When I prayed at the shrine, Goldrinn granted me another vision. I saw you standing astride the Lightning Ledge, with lightning in your hands. Goldrinn seems to feel that this is of the utmost importance, but I don't understand what the ancient has planned...\n\n{name}, go to the Lightning Ledge. Twilight's Hammer has been running experiments with something called a \"Lightning Channel.\" Investigate these channels, then use this totem to summon the Spirit of Goldrinn and see what he has in mind...", sourceObjective = "Collect a Charged Condenser Jar from a Twilight Lightning Channel.", progress = "We meet again, {class}. You carve a path of fear and confusion in your wake.", completion = "So, it is true! You indeed carry lightning in your hands.\n\nYou are the chosen one, {name}. You will be my champion, and carry my vengeance to realms where I cannot tread...", sourceObjectiveStatus = "unverified-source-field" }
quests[25354] = { id = 25354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweeping the Shelf", description = "The shrine is secure, the ogres in disarray. Enough. The time has come to go on the offensive.\n\nSomething sinister is underway above us, on the Lightning Ledge. It is time to unleash the fury of the ancients!\n\nFly up to the Lightning Ledge and demolish the Twilight's Hammer there. Crush them, {name}, slay their creations and hurl their bodies from the mountainside!", sourceObjective = "Slay 8 Twilight Stormcallers and 5 Howling Riftdwellers.", progress = "How goes the fight? I need not tell you how uneasy it makes me to have the Hammer's agents lurking above our heads.", completion = "Impressive, {name}. Very impressive.\n\nYou embody all of the strength of the wolf ancient, and possess the wisdom to use your powers well. I salute you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25355] = { id = 25355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning in a Bottle", description = "Lo'Gosh granted me a vision while you were in the hovel, {name}. I saw you striding across the Lightning Ledge, with lightning bolts in your hand. The vision was powerful: Lo'Gosh feels this is of utmost importance. We must not fail the ancient.\n\nUpon the Lightning Ledge, Twilight's Hammer has been experimenting with devices they call \"Lightning Channels.\"\n\nInvestigate one of these channels, then use this totem to summon the Spirit of Lo'Gosh and learn what the ancient is planning...", sourceObjective = "Collect a Charged Condenser Jar from a Twilight Lightning Channel.", progress = "We meet again, {class}. You fight well! You carve a path of fear and confusion in your wake.", completion = "So, it is true! You indeed carry lightning in your hands.\n\nYou are the chosen one, {name}. You will be my champion, and carry my vengeance to realms where I cannot tread...", sourceObjectiveStatus = "unverified-source-field" }
quests[25356] = { id = 25356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Summit", description = "We are staging a relief effort at Westreach Summit for all of Thousand Needles. Shyn will lend you my wind rider to safely get you there. Speak with Kanati Greycloud when you land.\n\nYou must go quickly if lives are to be saved!", sourceObjective = "Borrow a wind rider from Shyn and speak with Kanati Greycloud at Westreach Summit in Thousand Needles.", completion = "Jawn sent you? Good! We need your help, now!", sourceObjectiveStatus = "unverified-source-field" }
quests[25357] = { id = 25357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buy Us Some Time", description = "So many good men have been lost today. Without you, that number would be even higher.\n\nYou have our gratitude.\n\nIf what the shaman says is true, then there is no time to spare. The naga are scouring these waters looking for survivors.\n\nWe are not yet ready to fight. You must buy us time to make preparations. Find the naga that hunt us and delay their efforts.", sourceObjective = "Slay 8 Zin'jatar Raiders.", progress = "Have you given the naga something to think about, {class}?", completion = "Let's hope your efforts prove to be enough of a diversion...", sourceObjectiveStatus = "unverified-source-field" }
quests[25358] = { id = 25358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nerve Tonic", description = "How am I feelin', you ask?\n\nWell, after bein' yanked from the deck of our ship by a giant sea monster and then left to drown in the sea... not so good!\n\nMy nerves are gettin' the best of me, to be honest.\n\nIf you could round up some of the supplies that are sure to be floatin' around the nearby wrecks, I could likely whip up somethin' that'll take the edge off...", sourceObjective = "Mack wants you to collect 5 Sunken Cargo in Kelp'thar Forest.", progress = "Were ya able to grab some supplies, {race}?", completion = "I trust we both know what's been going on inside these crates...\n\nThat's right... ferrrmenntation! Here y'are. My personal secret recipe.\n\nYou wouldn't get this from any other guy!", sourceObjectiveStatus = "unverified-source-field" }
quests[25359] = { id = 25359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toshe's Vengeance", description = "You met Toshe back in Damplight Cavern, didn't you? He followed some of the fleeing naga to a set of ruins to the east and then sent for help.\n\nFind Toshe at the ruins as soon as you can. If you find out anything about what the naga want, please let us know.", sourceObjective = "Speak to Toshe Chaosrender at the Ruins of Thelserai Temple.", completion = "I remember you. You were there when they attacked us back in the cave.\n\nGood to have you with me, {class}. Ready for a little vengeance?", sourceObjectiveStatus = "unverified-source-field" }
quests[25360] = { id = 25360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crabby Patrons", description = "These crabs are not friendly. Not. Friendly.\n\nSam's endless drilling is riling them up. I know from experience that there's no stopping Sam, so let's look into the other side of things, shall we?", sourceObjective = "Kill 10 Green Sand Crabs.", progress = "Careful. They pinch.", completion = "Does everything down here only come in jumbo size? Oooh! That's a thought. Maybe there are some hunky sea goblins around here somewhere.\n\nThanks, by the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[25361] = { id = 25361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Cloak's Sheen", description = "Well met, {class}. I've traveled with my companions down to Feralas on a mission for our Orgrimmar masters.\n\nMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with the gorgeous wings I want are west of Camp Mojache.", sourceObjective = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.", progress = "The sprite darters can be dangerous critters when provoked. Be careful when dealing with them, {class}. And be even more careful of any night elves in the area. The pestering fools tend to hold up in the forests also.\n\nWhen you've gotten enough of the wings, let me know, I'll be sure to reward you well!", completion = "Wonderful, {class}! These will do nicely. There are enough here to make a cloak for Korrin, and possibly even more! Thank you.\n\nI hope the trip wasn't too dangerous? The area of Feralas is not known for being forgiving, but you've obviously done well enough.\n\nThank you again, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25362] = { id = 25362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Discovery", description = "The Grimtotem clan! Those gutless traitors are still lurking around here, eh...\n\nYou have to go back, {class}. Go back and bring me their horns... piles of them if you can. The Grimtotem are not to be trifled with or underestimated. Go back and slay them; let the rivers in Feralas run red with their dark blood.", sourceObjective = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.", progress = "Take my words seriously, {class}, the Grimtotem clan is evil. If you've found their whereabouts, then it's up to you to return and strike the first blow against their clan... before they can come into our own lands and raze our own villages, or pilfer our lands.", completion = "Traitors to the Horde and traitors to their own people...\n\nI guess they're not all bad. They'll make fine drinking flasks.", sourceObjectiveStatus = "unverified-source-field" }
quests[25363] = { id = 25363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Woodpaw", description = "The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.\n\nThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.\n\nGo!", sourceObjective = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.", progress = "We drive them back, and yet they still attack!  Someone or something must be driving them into a frenzy... oh, you have returned, eh {name}?  Do you have the manes I require for the bounty to be met?", completion = "This is proof of a good start, {name}.  Your skills as a soldier are to be commended.\n\nYou are not the only one I ask that task of.  Many before you have fought them, and in times past, our efforts have kept them at bay.  Recently though, their attempts to push northward into our area of influence have increased dramatically.  Their attacks have also become more savage... almost as if they were desperate.\n\nI have a plan though, {name}, that might settle things once and for all against them...", sourceObjectiveStatus = "unverified-source-field" }
quests[25364] = { id = 25364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Strike", description = "Gnolls are unfortunately as resilient as they are brutish and stupid. I have driven back the gnolls time after time from our camp, and it is only our chieftain's mercy that prevents them from being wiped out entirely.\n\nOver the years, it has fallen into a dance of strength and dominance. When their numbers surge and they threaten the camp, the alphas, the strongest gnolls, must be slain.\n\nThis will drive them back into the forest, and leave us is peace until they forget their lessons.", sourceObjective = "Kill 5 Woodpaw Alphas.", completion = "You've done as I have asked, and for that I salute you.  Take this small reward as compensation for your efforts, {name}.\n\nWith their numbers thinned and their leaders slain, the gnolls will think twice about storming the camp.  This doesn't conclude the issue at hand, however...\n\nThere must be some reason why the gnolls have been whipped into such a frenzied state.  Before they have a chance to regroup, I want to find out what is causing it.", sourceObjectiveStatus = "unverified-source-field" }
quests[25365] = { id = 25365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woodpaw Investigation", description = "Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity.  If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.\n\nI want you to head back to the Woodpaw and find anything that might resemble their battle plans.  They have to have something; their attacks have been too coordinated to be done without them.  Find them, and return to me when you have them.", sourceObjective = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.", completion = "Examining the map reveals it to be the battle plans that Hadoken Swiftstrider wants.  Numerous arrows that perhaps represent troop movements are drawn on the map, though most seem to be headed toward the south rather than to the north where Camp Mojache lies.\n\nAnother section of the map has a picture of what you think is a large insect of some kind, with various tick marks under it.  From the looks of the gnolls, it perhaps represents their losses against the unknown bugs...", sourceObjectiveStatus = "unverified-source-field" }
quests[25366] = { id = 25366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Plans", description = "With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.", sourceObjective = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.", progress = "Welcome back {name} - were you able to find some tangible evidence as to the plans of the gnolls?", completion = "Ah, this is exactly what we needed.  While I am not so skilled at ciphering what most of the scrawling on this map is, I've seen enough battle plans in my day to understand what is happening with the gnolls.  It looks like they are currently fighting a two front war.  One is with us... but it seems that their main energy has been against a foe to their south.\n\nThere's more at hand here than meets the eye.  Perhaps it is time to figure out who this other foe they face really is.", sourceObjectiveStatus = "unverified-source-field" }
quests[25367] = { id = 25367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash Infestation", description = "From what scouting we have managed to muster, we believe that the foe south of the gnolls is an insect-like race.  Frankly, it is irrelevant whether or not they're sentient.  If they are driving the gnolls to frenzy against us, then they are as big of a threat - if not more - than the gnolls.\n\nDive deep into where these Zukk'ash insects dwell; it is known as the Writhing Deep.  Thin their numbers and report back to me what you find, bringing back their carapaces as evidence of your handiwork.", sourceObjective = "Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas.", progress = "How goes the hunt, {name}?  Are you here to report your success?", completion = "Well done, {class}.  Though the extensiveness of the Zukk'ash presence will not be thwarted with anything less than a full-scale invasion, you have bought us some time so we can devise a proper strategy.\n\nI will be sure to have these carapaces analyzed; we'll need to learn everything about them before we deal with what has unfortunately turned into a much larger issue than we had anticipated.", sourceObjectiveStatus = "unverified-source-field" }
quests[25368] = { id = 25368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verinias the Twisted", description = "The other spirits and I are bound here by a cruel demon named Verinias. He is our captor, a twisted, mindless beast who devours our souls over milennia.\n\nThe lure of the souls and arcane magic you've brought me should let you draw him out. Take this condensed essence to the dead tree at the far north of the ruins. Use it to lure Verinias and slay him, that I may finally be free...", sourceObjective = "Defeat Verinias the Twisted.", completion = "I'm free...finally! Oh, it feels so good to be free...\n\nOh, you saw, didn't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[25369] = { id = 25369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinglasher", description = "In surveying the Writhing Deep, one of our scouts reported seeing a giant insect - much larger than the other insects spotted - wandering about the twisted terrain.  Not only is it larger, it also seems to secrete some sort of aura that the other insects don't.  We've given it a name - Stinglasher.\n\nThe innards of this beast would be invaluable to study as we figure out the best way to deal with this new threat.  Cut out its secretion glands and bring it back to me immediately!", sourceObjective = "Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas.", progress = "Have you managed to bring down Stinglasher yet?", completion = "Impressive, {class}... most impressive!  If Stinglasher is indeed one of their strongest creatures, the study of the beast will prove to be quite valuable in time.  It's now my charge to make sure we defend ourselves long enough to take advantage of it.\n\nPlease accept this coin bounty as a token of the entire camp's thanks, {name}.  Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[25370] = { id = 25370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inciting the Elements", description = "This is no mere natural occurrence, {name}.  There must be a twilight presence behind our lines that we haven't accounted for.\n\nIt's possible that whoever is instigating the elemental disturbance is using foul magic to hide themselves from our sight.\n\nSeek the aid of the faerie dragons that roam near the World Tree; they can see through any of our enemy's illusions.\n\nFeed them the juniper berries that grow nearby to gain their trust.", sourceObjective = "Feed Juniper Berries to the Faerie Dragons and slay 4 Twilight Inciters.", progress = "Back already, {name}?", completion = "You've done well, {name}.  We cannot allow the Twilight's Hammer spies this close to the world tree!", sourceObjectiveStatus = "unverified-source-field" }
quests[25371] = { id = 25371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abyssal Ride", description = "If you are going to be making it anywhere in this kelp forest, we need to get you a reliable mount. I think I've come up with a better plan than the sea turtle, and it's not far.\n\nTie off a lure at the rope just west of us, and then mount the seahorse that it will attract.\n\nBe warned, you may need to work hard to break the beast.", sourceObjective = "Lure and subdue an Abyssal Seahorse.", progress = "The grace of these creatures is astounding. They will make the perfect mounts.", completion = "Amazing! You look exhausted. She must have really made you work for it.\n\nLife should be a lot easier down here going forward with a mount that swift at your beckoning. Congratulations, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25372] = { id = 25372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aessina's Miracle", description = "<The finger-like branches of one of Nordu's burning limbs part, revealing an untouched, glimmering seed.>\n\nThis is the Heart of the Forest. The seed of life.\n\nTake this to your Arch Druid at Aessina's Grove - Hamuul Runetotem will know how to invoke its power. I promise you, the wilderness spirit will be silent no longer. New life will bloom from the ashes of old.\n\nThank you, {race}. My time is done.", sourceObjective = "Take the Heart of the Forest to Hamuul Runetotem at the Grove of Aessina in Mount Hyjal.", progress = "I am at my wit's end, {name}! Aessina is silent.\n\nHave you found something? What is this?", completion = "This is the key, {name}! With the seedlings you collected for me earlier, the animals you've saved from around Hyjal, and the Heart of the Forest you've just discovered, we can rejuvenate this land right from under the feet of Twilight's Hammer. Imagine their astonishment to see their work undone, as life triumphs over chaos...\n\nI will begin the ceremony at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[25373] = { id = 25373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hilltop Threat", description = "I am proud of Mojache's reputation as a safe haven in the wilds of Feralas, but the camp faces many threats. The Gordunni ogres gather nearby in the northern foothills, claiming their territory and despoiling the wildlife.\n\nWith the arrival of our brothers and sisters seeking shelter, I cannot let them linger any more. Go north and drive the ogres out.", sourceObjective = "Kill 5 Gordunni Hillguards.", completion = "I thank you, {name}, but there is more work to be done to keep the camp safe. Listen further.", sourceObjectiveStatus = "unverified-source-field" }
quests[25374] = { id = 25374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasquatch Sighting", description = "You may have seen this with your own eyes, but my longrunners have reported something disturbing to me. The gordunni in the hills have captured an enormous sasquatch from the wilds.\n\nI don't know how long it's been held, but ogres are not ones for hobbies. I fear they plan to unleash the tortured beast on Camp Mojache.\n\nReturn to the deepest corner of the Gordunni Outpost and slay the sasquatch, {name}.", sourceObjective = "Kill Bigfist.", completion = "I will be able to rest easy now, {name}. You've saved our camp from a terrible menace.", sourceObjectiveStatus = "unverified-source-field" }
quests[25375] = { id = 25375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming The Tamers", description = "The gordunni are not known to tame animals. If they're learning, this is cause for alarm. While the sasquatch they've tamed may be the major threat to our camp, the gordunni who captured him should be dealt with as well. If left, they may simply capture another.\n\nKill the gordunni tamers, and make sure the ogres know their efforts will not be tolerated!", sourceObjective = "Kill 6 Gordunni Tamers.", completion = "Good, good. Let's hope the ogres are at least smart enough to realize we're sending a message!", sourceObjectiveStatus = "unverified-source-field" }
quests[25377] = { id = 25377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde's Hoard", description = "It is unclear what manner of creature scrawled the seemingly random markings on this piece of parchment, but upon close inspection, some of the obscure shapes begin to look like landmarks.\n\nScanning the sea floor, you think you recognize a few points of reference, one being a nearby sunken ship. If your guess is correct, there appears to be treasure of some kind near the wreck.\n\nYou cannot help but wonder what the scaly, serpentine figure on the map might represent....", sourceObjective = "You must defeat Akasha to obtain the Horde Chest Key which you must then use to open the Sunken Horde Chest.", progress = "This slightly encrusted lock might still be functional.", completion = "You've discovered lost treasure!\n\nYour mind reels at the thought of what else might be hidden in the depths of the sea.", sourceObjectiveStatus = "unverified-source-field" }
quests[25378] = { id = 25378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Call", description = "The dragons of nature... Heed her call, {name}. Do not linger here. Her request for your aid is both a great honor and an omen of terrible danger.\n\nThe place she spoke of is called the Emerald Summit. A path off the main road through the Lower Wilds leads up one of the high stone plateaus; you will find a small shrine at the top.\n\nAll of Feralas may rest upon your shoulders. May the Earth Mother watch over you.", sourceObjective = "Speak with Ysondre at the Emerald Summit in the Lower Wilds.", completion = "You've come.\n\nI am ashamed to ask this of you, {class}, but I've ran from him long enough. Taerar must be stopped.", sourceObjectiveStatus = "unverified-source-field" }
quests[25379] = { id = 25379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taerar's Fall", description = "Emeriss and Lethon are gone. It's only us left now. I can hide from this no longer. All I did while a part of that brood...all the suffering I've caused...must be repaid today.\n\nI am still weak, {name}. I cannot assume my true form even if I dare try. But I will still stand beside you in battle.\n\nIf you are prepared, I will call Taerar to us. He will be unable to resist the temptation of revisiting corruption upon me.", sourceObjective = "Defeat Taerar.", completion = "It is done.\n\nThis land that has suffered so much can rest now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25381] = { id = 25381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Fire With ... Anything", description = "The inferno raging up ahead marks the front line between us and the forces of the Fire Lord. The fire elementals unleashed here are unlike any I've ever encountered.\n\nCan you help us stem the tide of destruction? Slay the raging firestorms... before they engulf Aessina's Grove and erase all hope of someday reclaiming this mountain!", sourceObjective = "Slay 10 Raging Firestorms within the Inferno.", completion = "Thank you, {name}. You've given us the opportunity to try to reclaim the upper hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[25382] = { id = 25382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting the Rituals", description = "The firestorms up ahead are unbound elementals in the purest form - something I didn't think could exist outside their own plane. Only very skilled summoners could unleash something like this.\n\n{name}, head into the Inferno and seek out Twilight Inferno Lords. They've got to be summoning in reinforcements as we speak. Silence them... For good!", sourceObjective = "Slay 6 Twilight Inferno Lords within the Inferno.", progress = "Tell me... have you found the fiends responsible for this?", completion = "Dead? Good!\n\nBut it seems there's still so much to be done... fires to quench... and the soil to heal...\n\nI hope you'll stay close and help us reclaim Hyjal!", sourceObjectiveStatus = "unverified-source-field" }
quests[25383] = { id = 25383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Farewell", description = "With that, I am the only one left.\n\nEven if I choose to remain in this world, I cannot rejoin the green flight. But this victory gives me hope. Perhaps, in time, I can find peace in a simple life among mortals.\n\nYou must return to your people. Tell them that the dragons of nightmare are gone, and will no longer threaten these lands.", sourceObjective = "Speak to Chief Spirithorn in Camp Mojache.", completion = "You are truly blessed by the Earth Mother, {name}, to have the honor of fighting with the guardians of nature, and to also survive it.\n\nKnow that you have kept safe every living soul in this camp, and possibly this entire forest. Take these gifts with my deepest thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[25384] = { id = 25384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raw Materials", description = "Thank you, {class}. We owe you our lives.\n\nBut if we're ever to see the surface again, we'll have to fight our way out of here. That means I'm going to need to craft some weapons and armor.\n\nBefore you found me, I saw a soldier eaten by one of those orca up there.\n\nI'll wager that if you cut a few of them open, you'll find plenty of scrap metal for me to work with.\n\nIf you don't want to swim up to them, I bet you could lure one down to you with some entrails...", sourceObjective = "Samir wants you to collect 3 Rent Scrap Metal from Frenzied Orca in the Kelp Forest.\n\nYou can lure an orca using Pincer Entrails from Clacksnap Pincers.", sourceObjectiveStatus = "unverified-source-field" }
quests[25385] = { id = 25385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save the Wee Animals", description = "Help us, {class}! The forest is aflame, and the wee animals can't find their way out. They can't fight for themselves, with their teeny-tiny little teeth and their soft furry paws! They're fluffy and sweet.\n\nThey have wet little noses!\n\nIf you don't save them, I don't want to even THINK about it.\n\n<She slaps her palms over her eyes.>\n\nI'm not thinking!", sourceObjective = "Go into the Inferno and rescue any combination of 10 Panicked Bunnies or Terrified Squirrels.", progress = "Did you save the wee animals? And their wee little friends?", completion = "Squueeeee!\n\nDid the nice Mr. {class} pull you from the flames, little friend? You're safe now!\n\nHooray!", sourceObjectiveStatus = "unverified-source-field" }
quests[25386] = { id = 25386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Stonemaul Hold", description = "You must send word of what has happened here, {name}. To the south is Stonemaul Hold. There, our allies have gathered the few ogres of the horde to fight against those despoiling these forests.\n\nSpeak with Orhan Ogreblade. She leads the Stonemaul clan here, and will need to know of all that has occured. And be wary, lest some of this corruption remain...", sourceObjective = "Speak with Orhan Ogreblade in Stonemaul Hold.", completion = "You've been tussling with drakes, eh?\n\nI like it. We need someone who can pull their own weight around here. Are you ready to fight for the Horde?", sourceObjectiveStatus = "unverified-source-field" }
quests[25387] = { id = 25387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Camp Mojache", description = "You've done a hell of a job here, {name}. With the Twilight's Hammer shamed and the Gordunni left bleeding and broken, we'll be able to set our sights on the true battle with the Alliance here.\n\nIt'll take time to build our forces enough to match the night elves infesting this place. I'm sending you ahead to Camp Mojache to the east; they've got problems of their own, and we can't let any Horde territory fall here.\n\nLok'tar!", sourceObjective = "Speak with Chief Spirithorn in Camp Mojache.", completion = "I am thankful you've come, {class}. Our camp is beset by many perils, and yet we must tend to those fleeing the devastation of the cataclysm.\n\nIf there is to be any refuge here, you must help us.", sourceObjectiveStatus = "unverified-source-field" }
quests[25388] = { id = 25388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crate of Crab Meat", description = "This crate, labeled 'Crab Meat', seems to have fallen from a recently sunken cargo ship.\n\nAdarrah would surely welcome such a find, considering the ordeal she's had to endure.", sourceObjective = "Take the Crate of Crab Meat to Adarrah in Smuggler's Scar.", progress = "What have you got there, {name}?", completion = "Why, {name}! What a surprise!\n\nIf anyone ever calls your character into question you be sure to send them my way.\n\nI'll tell anyone who'll listen that you really helped me out in a pinch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25389] = { id = 25389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste For Tail", description = "It could be days before we're ready to make our way to the surface, and to be honest, I'm already beginning to get hungry.\n\nI hate to be picky, but when it comes to seafood, I'm afraid there are very few things I can stomach.\n\nIf you come across any lobster types, I would happily pay you what coin I have with me for their tails.", sourceObjective = "Adarrah wants you to bring her 4 Clacksnap Tails.", progress = "Oh, please tell me you were able to find me some food, {class}.", completion = "Oh, my!\n\nThat's some of the biggest, juiciest tail I've ever seen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25390] = { id = 25390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Girl's Best Friend", description = "Let's just get it out in the open. I'm no stranger to love, {name}.\n\nOver the years, if there's one thing I've learned, it's that love's tangible treasures last longer than the flames of passion.\n\nI've managed to collect my fair share of these gifts - gemstones, rings, necklaces, and the like, and I carry them with me wherever I go.\n\nAt least I used to...\n\nWhen I was swept from the ship, my valuables were scattered across the sea. Help me recover them and I promise to make it worth your trouble.", sourceObjective = "Adarrah wants you to recover 6 Adarrah's Keepsakes.", progress = "Well, {race}?\n\nWere you able to recover my valuables?", completion = "Oh, you've found them! I was sure they were lost forever...\n\nHere you are, {name}. I hope this is ample payment.", sourceObjectiveStatus = "unverified-source-field" }
quests[25391] = { id = 25391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Spirit", description = "Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.", sourceObjective = "Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.", completion = "As promised, you have your choice, {name}. The muisek of the creatures has been forever sealed into the power of these weapons.\n\nYou may now wield their energy as your own. Use it well.", sourceObjectiveStatus = "unverified-source-field" }
quests[25392] = { id = 25392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, Deer!", description = "Do you speak deer? It's all in the nose.\n\n<She points to her nose.>\n\nThe does have fled the fires, but their little fawns - Some of them are still trapped in the burning and the hurt!\n\nGo back into the Inferno and escort three injured fawns back here to their mothers right here beside me.\n\nPlease save the little fawns, or I'll give you the big eyes!\n\n<Her eyes grow big and dewy.>", sourceObjective = "Rescue three Injured Fawns from The Inferno and escort them back to Mylune at the Grove of Aessina.", progress = "Hurry! I can smell the smoke!", completion = "Oh yay! Happy little deer!\n\nNow they can grow up and have ADVENTURES.\n\nYou're swell.", sourceObjectiveStatus = "unverified-source-field" }
quests[25393] = { id = 25393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Gnomeregan", description = "Momentarily, the multi-phased assault upon Gnomeregan will begin and Mekgineer Thermaplugg and his men will be brought to justice!  Too long has Thermaplugg festered in the depths of our home, defended by a corrupt and irradiated army.\n\nThe assault begins in but a moment! Be ready recruit, this fight will not be for the faint-hearted.", sourceObjective = "Help King Mekkatorque with the assault on Gnomeregan.", completion = "Curses! We had to fall back. But Thermaplugg's lost, and he knows it... he's only bought himself time. We hold the surface, and when the radiation clears we'll assault and recapture Gnomeregan with a force twice this size.", sourceObjectiveStatus = "unverified-source-field" }
quests[25394] = { id = 25394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Illness", description = "I've discovered a brood of dragon whelps gathered off the road to the north with a similar affliction. Green dragons are sacred custodians of nature. The fact that this disease is capable of spreading to them is cause for great alarm.\n\nWe must stop this from spreading further through any means. Slay the infected whelps, {name}, and return to me.", sourceObjective = "Kill 10 Noxious Whelps.", completion = "This development worries me greatly. This has happened before...", sourceObjectiveStatus = "unverified-source-field" }
quests[25395] = { id = 25395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stolen Keg", description = "You've got to help us, <lad/lass>. We were tasked with escorting a precious cargo to our fellow dwarves...a keg full of the finest ale you can get out here!\n\nUnfortunately, bird-brain over here fell asleep on the job! Those blasted orcs took our keg, and hauled it up into Dun Algaz where they're hiding.\n\nThis can't stand! Now, while I stay here and try to convince this idiot that it was his fault, I'd like you to go in there and get our keg back. For Khaz Modan!", sourceObjective = "Retrieve the Mountaineer's Ale from Dun Algaz.", progress = "Do you have it? Is the poor thing intact?", completion = "Thank the Makers! It's downright pristine. Those orcs couldn't figure out the tap-lock, it seems...and couldn't hack through the mastercraft work of Ironforge's keg-crafters with their crude weapons!", sourceObjectiveStatus = "unverified-source-field" }
quests[25396] = { id = 25396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears of Stone", description = "As you witnessed, the dragon Ysondre has told us that the tears of the land can seal the portal from which this corruption stems.\n\nHer words ring true; in the glade to the west, I have seen the mountain giants distraught. They raged in frustration and wept, and their tears fell upon the stones as shining crystals.\n\nThough the giants weep no more, these stonetears must be what Ysondre referred to. We must gather them.", sourceObjective = "Collect 7 Stonetears.", progress = "The tears are among the very rocks that the giants themselves rise from. There should be loose ones near the base of these large monoliths.", completion = "The mountain giants are precious allies of our race. We must stop this corruption before it claims any more creatures of the forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[25397] = { id = 25397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Land, Corrupted", description = "The cliff giants of Feralas are extensions of the earth itself, {name}. When nature thrives, they are benevolent protectors and peaceful guardians.\n\nBut as the forest is tainted, so too are they.\n\nShould they be corrupted by this malady, they will lash out in violence against trees, wildlife, and the very boulders they were shaped from.\n\nBe wary in your tasks. Should you find any corrupted giants, destroy them, for the sake of those still spared.", sourceObjective = "Kill 6 Corrupted Cliff Giants.", completion = "The spirits of these guardians will return in time, {name}. You've freed them to move on in nature's cycle.\n\nNow it falls to us to make sure that cycle is free of corruption and needless suffering.", sourceObjectiveStatus = "unverified-source-field" }
quests[25398] = { id = 25398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Dream", description = "It is ready. Take this, {name}; a beacon of natural essence, blessed by the will of Ysondre.\n\nTo the north, on the other side of the flowing brook, is Dream Bough. There stands the Great Tree, the tallest in Feralas, a sapling of the very World Tree. A portal to the heart of the Emerald Dream sits in its trunk, and it is this portal you must seal.\n\nThe portal will be guarded, but you must be brave.", sourceObjective = "Use Ysondre's Tear to seal the portal at Dream Bough.", completion = "Your bravery has seen us through! The Emerald Nightmare has been shut out from this land.\n\nThe fate of the dragon Taerar worries me...but there is much work still to be done. I cannot afford to dwell on it.", sourceObjectiveStatus = "unverified-source-field" }
quests[25399] = { id = 25399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatecrest Forces", description = "The Hatecrest are fighting fiercely! Their leader is a priority, but we need to kill as many of them as we can.\n\nGo ahead of me, I'll meet you on the battlefield. Show them no mercy!", sourceObjective = "Kill 10 Hatecrest Naga.", completion = "Your valor was mentioned in my briefings, {name}. I commend you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25400] = { id = 25400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Threat", description = "Estulan, the Highborne up in the tower, is reclusive. I haven't been able to speak to him very much. He has, however, told me that the ruins of the High Wilderness to the south are full of Gordunni ogres.\n\nThe ogres are not only a threat, they're destroying any forest and wildlife nearby. Estulan has also warned me of what might happen if they discover any artifacts of Highborne power among the ruins...\n\nHead south, {name}, and slay any Gordunni you find!", sourceObjective = "Kill 16 Gordunni ogres in the High Wilderness.", completion = "It sounds like there were more than we thought! Thank you for your brave work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25401] = { id = 25401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Orb", description = "In addition to clearing out the ogres...\n\nEstulan mentioned something else about the ogres. He said the ogre warlocks may have some sort of orb, or other item of power\n\nHe was terse about it, but seemed upset...he said there was \"no way they could be Highborne\", so I think he wants to know just where they got them. Bring me back one of these orbs.", sourceObjective = "Collect a Gordunni Orb from a Gordunni Warlock.", progress = "Do you have the orb?", completion = "Is that it? Let me see here...", sourceObjectiveStatus = "unverified-source-field" }
quests[25402] = { id = 25402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Estulan's Examination", description = "He's right. I haven't been among the night elves long, but I can tell these markings are completely unlike any kaldorei decorations...\n\nEstulan needs to see this. Take this up the tower to him. He may be surly, but don't be dissuaded; once he sees the orb, he'll realize it's an important issue.", sourceObjective = "Deliver the Gordunni Orb to Estulan.", progress = "What is that you're holding?", completion = "Ahh, the orb I mentioned before. A decent reason to disturb me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25403] = { id = 25403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Abduction", description = "This is neither a crude ogre trinket, nor an ancient relic made by my kind. Its specific construction is new to me...and this fact disturbs me greatly.\n\nThe wolf-girl will be sending you to Dire Maul soon, to fight the Gordok elite. They are the leaders of the Gordunni, and would know who is supplying these.\n\nTake the orb back, I've cast a few enchantments on it. Hold it up in front of a weakened Gordok ogre, and once you've captured him, bring it back here.", sourceObjective = "Use the Modified Soulstone to capture a Gordok ogre.", completion = "Ah, you've brought him. Now I merely have to suffer the fate of speaking to him.", sourceObjectiveStatus = "unverified-source-field" }
quests[25404] = { id = 25404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You're Not Against Us...", description = "South of here you'll find a solitary tower, known as \"Blackhorn's Penance.\" Upon it is bound a demon: Tyrus Blackhorn.\n\nYou may think me mad for turning to an old foe for help, but Blackhorn was once a mortal, and I can't imagine he wants to watch Twilight's Hammer triumph.\n\nSpeak with Blackhorn, and see if you can convince him to help us in our fight. He may yet redeem himself.\n\n...Just don't set him free!", sourceObjective = "Speak with Tyrus Blackhorn and convince him to help in the fight against the Twilight's Hammer.", progress = "You were sent here to talk, {race}. So. Talk.", completion = "Very well, {race}. I will help you mortals, even from within my bonds.\n\nBut don't sicken me by claiming it's my redemption. I do this for my own ends.", sourceObjectiveStatus = "unverified-source-field" }
quests[25405] = { id = 25405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rest For the Weary", description = "You have done well, {race}, but there is much more to do and I grow weary.\n\nI have expended a great deal of energy sending a distress message to Earthen Ring leadership, pleading for their help.\n\nI must rest if I am to be of further use to us here.\n\nSpeak to the leader of the men you've saved and do what you can to help them prepare for battle.\n\nThe naga are scouring the waters for us. It is but a matter of time before they return - and they will surely come in even greater force.", sourceObjective = "Speak with Captain Taylor.", completion = "I hear you, {race}.\n\nI understand the urgency, but these men are in no condition to fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[25406] = { id = 25406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordok Guards", description = "With the nearby ogres dealt with, we should take the offensive and press our attack into their territory.\n\nThe Gordok ogres are the head of the Gordunni clan, ruling them from the ruins now called Dire Maul. They are stronger than the lesser Gordunni, but I have no doubt you can handle them, {name}. They won't know what hit them.", sourceObjective = "Kill 6 Gordok Enforcers and 6 Gordok Ogre-Mages.", completion = "Wonderful! Everything's going according to plan. Lady Shandris will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[25407] = { id = 25407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Wisps", description = "The Sentinels make up the bulk of our forces here, but a well-rounded night elf army requires more than just night elves. The creatures of this forest, our ancestral home, have protected us for centuries. We simply need to rally them.\n\nTake this whistle. Our allies know this sound, and you'll be using it to recall them.\n\nBefore you start gathering creatures, I'd like you to recall a few of our wisps, just for practice. You can find them just outside the fortress, among the trees.", sourceObjective = "Use Tessina's Whistle to recall 3 Feathermoon Wisps.", completion = "Wisps have always lived in harmony with night elves, and we depend on them for many things. These little guys you sent back, for example, will be helping us with some new construction and repairs.\n\nReady for more?", sourceObjectiveStatus = "unverified-source-field" }
quests[25408] = { id = 25408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of Their Demise", description = "We will decimate the Twilight's Hammer by corrupting and subverting them. \n\nSeeing that you have no intention of releasing me from my bonds, I require you to collect some reagents for me. My own demonic essence has corrupted the plant life around my shrine here. I need you to harvest some bileberries from the wailing weeds that surround this tower.\n\nMy little pets will attempt to harvest YOU in return. Try not to let them agitate one another.", sourceObjective = "Collect 8 Bileberries.", progress = "Has the local flora been giving you a hard time?\n\n<Blackhorn grins disturbingly.>", completion = "Very good. Please crush the berries into a pulpy liquid. That's quite an aroma isn't it?\n\nNow now, don't gag. It's beneath you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25409] = { id = 25409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Hippogryphs", description = "Hippogryphs are majestic creatures. Some say they were created by Cenarius himself as a gift for the night elves. They're wary of other races, but they're intelligent enough to recognize a friend of a friend.\n\nI need more hippogryphs here so we can begin training some of our newer archers to ride them. Take the whistle again and rally the Frayfeather hippogyphs in the grove just south of the Tower of Estulan.", sourceObjective = "Use Tessina's Whistle to rally 10 Frayfeather Hippogryphs.", completion = "A properly trained squadron of hippogryph riders can take on nearly any opposing force. Feathermoon Stronghold will be much safer with these noble beasts on our side.", sourceObjectiveStatus = "unverified-source-field" }
quests[25410] = { id = 25410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Treants", description = "Some people think treants are good for little more than fetching drinks in a war. Most of them haven't seen an entire defensive line scattered by what they thought was cover.\n\nAnd have you ever seen a peon try to chop one down and get surprised? I was in tears...\n\nAt any rate, they're immensely valuable allies. You'll find some wandering just outside  the Tower of Estulan and more in forest to the east, just southeast of Dire Maul. Be on the lookout for the Horde!", sourceObjective = "Use Tessina's Whistle to rally 6 Wandering Forest Walkers.", completion = "They may not look it, but some treants grow to be ancient protectors. We could use a few more of those around here...", sourceObjectiveStatus = "unverified-source-field" }
quests[25411] = { id = 25411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Master", description = "The potion you created is vile enough to wake the dead. Which is its intended purpose.\n\nSlay a Twilight Inferno Lord and force the brew down his throat. He will revive, if only briefly, and be completely under your dominance.\n\nSpeak with him and learn the true name of the fire elemental he is channeling into the world to burn down your precious forest.", sourceObjective = "Use the Bottled Bileberry Brew on the corpse of a Twilight Inferno Lord, then speak with him.", progress = "<The wavering corpse is animated briefly by foul magic.>\n\n<It doesn't acknowledge your presence.>", completion = "<The wretched creature before you speaks in a wavering voice, its body broken but briefly animated by Blackhorn's vile potion.>\n\nYes, master?", sourceObjectiveStatus = "unverified-source-field" }
quests[25412] = { id = 25412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Name Never Spoken", description = "We called upon the fury and flame of the One, my former master.\n\nThe Inferno is by His design.\n\nHis true name is never uttered, it holds His power.\n\nEach of us was told but a piece. Each piece engraved on a firestone.\n\nThe One's true name is here, in the Inferno. Seek the three stones...", sourceObjective = "Assemble the true name by examining the three Firestones.", completion = "Yes, yes! Show me the runes you discovered.\n\n\"Vol'talo Thol'embaar.\" That's the name of your real enemy.\n\nPresumably you're dealing with one of Ragnaros's generals, sent here to scorch the mountainside and pave the way for his conquest.\n\nI will show you how to crush him.", sourceObjectiveStatus = "unverified-source-field" }
quests[25413] = { id = 25413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Change of Plans", description = "Alright, kid. Slight change of plans...\n\nI think I've figured out a way to finish off that monster and you're going to assist me.\n\nThe way I see it, you owe me until my work is done here, and I ain't leaving without that artifact.\n\nFirst I need you to search those old wrecks for some good rope and a serviceable harpoon.\n\nThen... well, I'll fill you in on the rest later.", sourceObjective = "Get the Rusty Harpoon and 3 Coils of Rope.", sourceObjectiveStatus = "unverified-source-field" }
quests[25419] = { id = 25419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady La-La's Medallion", description = "Dozens of crude gold links make up this heavy chain.\n\nDangling from the center link is an opalescent fragment of what must have once been a large shell-shaped medallion.\n\nYou wonder if the other fragments might be nearby, and if the medallion might be reassembled into its original state.You will be able to choose one of these rewards:", sourceObjective = "Collect the 5 Medallion Fragments from Gilblin Collectors and combine them to create Lady La-La's Medallion.", sourceObjectiveStatus = "unverified-source-field" }
quests[25420] = { id = 25420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Obstacles", description = "I've studied the gate here for years, trying to find a way of entry that wouldn't disturb any of the ancient architecture just behind it. It figures a few overgrown earthquakes decided to muck the whole thing up! But what's done is done, and the entrance to Uldum is revealed.\n\nI wasn't expecting anything to come out of the ruins before we went in, though. A whole mess of golems are running amok in the valley now, let loose from inside. Someone needs to clean them up if we're gonna get in there!", sourceObjective = "Destroy 6 Sandstone Golems.", completion = "Good work, {class}. We're that much closer to the secrets of Uldum.", sourceObjectiveStatus = "unverified-source-field" }
quests[25421] = { id = 25421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Tablet", description = "At the bottom of the chest, you find a large tablet. Made of a material resembling stone, but completely smooth and flawless, it is covered in strange writing.\n\nWhile some resembles the writing on the walls, other scripts appear completely different. Gunstan would probably like to see this.", sourceObjective = "Take the Grand Tablet to Gunstan.", progress = "You're back! What have you found?", completion = "This is amazing. These hieroglyphs are undoubtedly titan, but the markings below it...\n\nIf I had to hope, this is the same passage written over and over again in an entire assortment of ancient languages. We might be able to use this to decipher the hieroglyphs! If the antechamber was covered in them as you say, who knows what else we'll learn.\n\nI'd like to grant you a fine reward, {name}. We've made the find of the century!", sourceObjectiveStatus = "unverified-source-field" }
quests[25422] = { id = 25422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkmist Legacy", description = "I am chained to this place...it takes so much effort just to speak to you. I can barely maintain this shape.\n\nI could help you, but please, help me pull myself together first. Once I'm more focused on this plane, I should be able to do it...\n\nIf I could just leave this tomb, the soil itself outside is full of ancient arcane deposits, laying forgotten for centuries. Could you bring me some?", sourceObjective = "Collect 6 piles of Glowing Soil.", progress = "Do you have the soil? I'm having trouble staying together...hurry...", completion = "Thank you! Thank you...\n\nI feel much better. With just a bit more...", sourceObjectiveStatus = "unverified-source-field" }
quests[25423] = { id = 25423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Suffering", description = "You must be careful when you venture forth. Other spirits are bound to this place, malevolvent and hateful ones. They've all suffered so much.\n\nNone of what they used to be remains, only suffering and a will to live. We will need that will to summon the overlord that keeps me bound here. Please, gather the essence of the spirits, and bring it back to me.", sourceObjective = "Collect 6 Soul Essences.", progress = "Have you gathered it?", completion = "You can feel their anguish, can't you?\n\nMy poor friends. At least we can use you to fix things...", sourceObjectiveStatus = "unverified-source-field" }
quests[25424] = { id = 25424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Alysra", description = "I thank you for freeing me, {name}.  I will tell our allies of my findings.\n\nI suggest that you return to the emerald dragon that sent you.\n\nThe Twilight's Hammer does not just seek to gain territory with this particular attack.  They're also after a prisoner.\n\nFandral Staghelm is being held in the Barrow Dens.  The attack doubles as a distraction to free him.  To what end, I cannot tell.  Perhaps our dragon ally can shed some light on this.", sourceObjective = "Return to Alysra at the Ruins of Lar'donir in Hyjal.", completion = "This development is troubling, {name}.  We must act swiftly.", sourceObjectiveStatus = "unverified-source-field" }
quests[25426] = { id = 25426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Woodpaw", description = "The first of Shandris's direct orders is to deal with the Woodpaw gnolls here. They've been spreading too far, too fast, and are becoming a threat to both the forest and our war effort.\n\nThey know we're here. After we took this camp, we've been leading covert strikes against them. It's time to make a major blow; bring back ten of their manes, and we'll be ready for the next phase.", sourceObjective = "Collect 10 Woodpaw Gnoll Manes.", progress = "The manes aren't just for trophies. If there's to be slaughter, we may as well not let it be a total waste.", completion = "Excellent work, {name}. I didn't think those gnolls would give you much trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[25427] = { id = 25427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Strike", description = "Never underestimate a threat. These gnolls may seem like simple brutes, but there's animal cunning even among them.\n\nThe gnolls run as a pack, and every pack has Alphas: The biggest, strongest, and most ruthless members that claw their way to dominance. They're the ones giving orders, so they're the ones we're going to slay now.\n\nThey reside mostly around the Woodpaw Den, pushing the others around. Get out there and push harder.", sourceObjective = "Kill 5 Woodpaw Alphas.", completion = "Perfect. Any gnolls left will be simple prey, lost in the woods.\n\nHeh...here, soldier, take your reward before I get distracted. We've got other threats to deal with.", sourceObjectiveStatus = "unverified-source-field" }
quests[25428] = { id = 25428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Heart of Flame", description = "Now you will use our newfound knowledge to pull Thol'embaar into the mortal plane like a babe screaming from the womb. Then you will crush him.\n\nThe ritual is simple: take this charred branch, tap it on the ground three times, and utter his name aloud.\n\nYou must call him from within the heart of the Inferno. Destroy him, and bring his black heart back to me.", sourceObjective = "Use the Charred Branch within The Inferno to Summon Thol'embaar. Kill him and take the Black Heart of Thol'embaar.", progress = "Tell me! Have you fought Thol'embaar yet?\n\nI am living vicariously through you, {race}. Do not disappoint!", completion = "There it is! Such a trophy! Born in the fires of another plane...\n\nGo ahead, {race}. Crush it. Crush his charcoal heart in your hands and let the winds scatter the ashes... yes, yes.", sourceObjectiveStatus = "unverified-source-field" }
quests[25429] = { id = 25429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash Infestation", description = "With the gnolls out of the way, we're ready to take care of other foes. Our scouts have discovered what appears to be a hive nearby, extending deep beneath the ground.\n\nThe insects of the hive are large and ferocious, and most likely pose an even greater threat than the gnolls. I want you to proceed to the hive with caution. Cut down a good portion of the bugs and bring back their carapaces for further study.", sourceObjective = "Collect 20 Zukk'ash Carapaces.", progress = "How goes the hunt, {name}?  Are you here to report your success?", completion = "These are silithid after all...I wasn't sure, having never seen one in person. Gilneas had its problems, but at least we didn't have these monstrosities running around!", sourceObjectiveStatus = "unverified-source-field" }
quests[25430] = { id = 25430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Allies", description = "The druids of Hyjal are not the only ones sworn to defend this land.  The emerald dragons have once again become a powerful ally to our cause.\n\nSpeak to Alysra at the Ruins of Lar'donir, to the north, and see what you can do to help.", sourceObjective = "Speak to Alysra at the Ruins of Lar'donir in Mount Hyjal.", completion = "My duties are here, viewing the enemy's movement from above, commanding our armies where they're needed.\n\nYour aid would be most welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[25431] = { id = 25431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinglasher", description = "Most of the insects we've seen wandering the hive have been enormous enough, but my scouts reported an especially huge one. It's supposedly a massive wasp, and it seemed to be directing the workers on the surface.\n\nI don't know much about these things, but if they're starting to wander beyond that pit in the ground, we need to put a stop to it. Kill this giant wasp and return to me.", sourceObjective = "Kill Stinglasher in the Writhing Deep.", completion = "Well done, {name}! You're proving very valuable to securing this area for the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[25432] = { id = 25432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Not \"Ogre\" Yet", description = "We dealt the Gordunni ogres a large blow at Dire Maul, but we haven't quite finished the job. My scouts have reported a group of them amassed in the hills to the north, gathering for some reason.\n\nIt's possible they're interested in the Horde settlement nearby, but I don't want to take any chances. Scout the area, kill any ogres you come across, and report back.", sourceObjective = "Kill 5 Gordunni Hillguards.", completion = "It's good to see you back. We've learned more about the ogre situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[25433] = { id = 25433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasquatch Sighting", description = "You may have seen it yourself, but other scouts have discovered an enormous beast being held by the ogres. Reports say it looks like a sasquatch, but if it is, it's the biggest ever seen in Feralas.\n\nThe ogres are most likely trying to teach it to obey them. While that's almost comical, I'm not going to sit by and let them train that thing to roll over at their command. Return to the hills and slay it.", sourceObjective = "Kill Bigfist.", completion = "Well done once again, {name}. Yet another threat removed from Feralas.", sourceObjectiveStatus = "unverified-source-field" }
quests[25434] = { id = 25434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming The Tamers", description = "The sasquatch may be a larger threat, but we also need to wipe out the ogres. The Gordunni have been a nuisance to us for too long, and Lady Shandris wants them completely gone.  Let's hope these are the last ones.\n\nKill the Gordunni tamers that keep the beast chained, and make sure they know the price of their meddling.", sourceObjective = "Kill 6 Gordunni Tamers.", completion = "Good work, and good riddance. I hope we never have to see another ogre here again!", sourceObjectiveStatus = "unverified-source-field" }
quests[25435] = { id = 25435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressure is Mounting", description = "G'day, <laddie/lassie>.\n\nThe name's Rendel.\n\nSeems ol' Moanah and I got here in the nick of time, eh?\n\nErunak wasn't kiddin' when he said it was life or death!\n\nWhile he's tryin' to find us a safe place to hole up, I'm gunna take a stab at securin' you a critter to ride.\n\nNow, I may not be up on all the ins an' outs of life in the sea, but it looked to me like them naga know how to get around down here.\n\nYou round up a few widgets for a bridle and I'll work up an enchantment.", sourceObjective = "Collect 3 Shark Sinews from Ravenous Threshers and 2 Sharpened Crab Claws from Sabreclaw Skitterers.\n\nRavenous Threshers can also be summoned to you by using Crab Entrails.", sourceObjectiveStatus = "unverified-source-field" }
quests[25436] = { id = 25436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiteful Sisters", description = "Something truly disturbing has occured. While on patrol, several of my scouts were ambushed by dryads.\n\nThe dryads are close allies of the night elves and guardians of the forest. I assumed they were just frightened by the sight of worgen, but the sentinels I sent out afterwards were also attacked.\n\nWhatever is going on, I don't like it. I want you to go investigate as well. If even the dryads have been corrupted...put them to the sword.", sourceObjective = "Kill 8 Corrupted Dryads.", completion = "I didn't want to scare you, but this is a grave situation. If the portal at Dream Bough was sealed, and the corruption is still spreading...", sourceObjectiveStatus = "unverified-source-field" }
quests[25437] = { id = 25437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Call", description = "A dragon of the emerald dream... what have you gotten yourself involved in, {name}?\n\nI wouldn't keep her waiting if I were you. The place she spoke of is what we call the Emerald Summit. A path off the main road through the Lower Wilds leads up one of the high stone plateaus; there's a small shrine at the top.\n\nGood luck, {name}. I hope to see you back safe.", sourceObjective = "Speak with Ysondre atop the Emerald Summit in the Lower Wilds.", completion = "You've come.\n\nI am ashamed to ask this of you, {class}, but I've ran from him long enough. Taerar must be stopped.", sourceObjectiveStatus = "unverified-source-field" }
quests[25438] = { id = 25438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Farewell", description = "With that, I am the only one left.\n\nEven if I choose to remain in this world, I cannot rejoin the green flight. But this victory gives me hope. Perhaps, in time, I can find peace in a simple life among mortals.\n\nYou must return to your people. Tell them that the dragons of nightmare are gone, and will no longer threaten these lands.", sourceObjective = "Speak to Adella at Shadebough.", completion = "To be drawn into a fight between dragons...I don't know if you're blessed or cursed.\n\nLady Shandris has heard of all you've done, and has personally sent this reward for your bravery. I'm glad you came back in one piece to receive it.", sourceObjectiveStatus = "unverified-source-field" }
quests[25439] = { id = 25439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeful Heart", description = "These are the naga that took our people. I only need one to interrogate, kill the rest.\n\nShow no mercy, {class}, for they would surely show us none.", sourceObjective = "Kill 10 Zin'jatar Ravagers.", progress = "These naga have ignited a fire in me that is not easily quenched.", completion = "Good to have a real warrior at my side. Too often, my shaman brethren can't seem to stomach the work.", sourceObjectiveStatus = "unverified-source-field" }
quests[25440] = { id = 25440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fathom-Lord Zin'jatar", description = "The Fathom-Lord is here, at the far side of the ruins. He's still injured from our last battle.\n\nI'll leave this pleasure to you. Make sure he doesn't get away this time.", sourceObjective = "Kill Fathom-Lord Zin'jatar.", progress = "Waiting on something? I thought you'd appreciate the opportunity to handle this yourself.\n\nDid I misjudge you?", completion = "And with this, hopefully their attacks on us will calm for a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[25441] = { id = 25441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex", description = "I have no fondness for snakes, and even less so down here. Fortunately for us, the watery elements still bend to my will for now.\n\nTake these globes and throw them at the ground to send the nearby water into a vortex, pulling in all the nearby serpents. The naga will most certainly turn the snakes against us, so keep the orbs close at hand.", sourceObjective = "Use the Globes of Tumultuous Water to trap 30 swarming serpents.", completion = "Too often, we are mistaken for druidic types. Perhaps that's true for some shaman, but do not let yourself be plagued by the ignorant belief that we are always peaceful.\n\nNothing about what I do is harmonious. I command the elements to my will. There is nothing offered in return. I would have it no other way.", sourceObjectiveStatus = "unverified-source-field" }
quests[25442] = { id = 25442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pearl of Wisdom", description = "This pearl is unlike anything you've ever seen before. It radiates light, and if you are not mistaken, it radiates powerful magic as well.\n\nEarthmender Duarn back in Silver Tide Hollow will surely be interested in this.", sourceObjective = "Bring the Luminescent Pearl to Earthmender Duarn in Silvertide Hollow.", progress = "Yes, {class}? Have you found something?", completion = "What is this? A pearl? Much more I think.\n\nThis is exactly what I was looking for, thank you for bringing it to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25443] = { id = 25443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Name Never Spoken", description = "Did my drought work? You spoke with one of them?\n\nThen you know what to do. The name of their elemental master is written on three firestones scattered throughout the Inferno. Examine each of these stones and we will have the name we need.\n\nHurry! Your precious forest burns!", sourceObjective = "Assemble the true name by examining the three Firestones in the Inferno.", completion = "Yes, yes! Show me the runes you discovered.\n\n\"Vol'talo Thol'embaar.\" That's the name of your real enemy.\n\nPresumably you're dealing with one of Ragnaros's generals, sent here to scorch the mountainside and pave the way for his conquest.\n\nI will show you how to crush him.", sourceObjectiveStatus = "unverified-source-field" }
quests[25444] = { id = 25444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Perfect Spies", description = "Now, it would be foolish to go in blind 'ere, so I be creatin' some tiny spies to gather information for Vol'jin. He got to know what's goin' on over on de islands.\n\nI could use da help, if you be feelin' up to it. I tell ya how it's done. First, ya gotta catch de frogs. Dey like to stay in de shade of da palm trees around Sen'jin.\n\nOnce ya have de frogs, bring 'em over here to my sentry totem an' attune dem to me sight.", sourceObjective = "Capture 5 Sen'jin Frogs and attune them to Vanira's sight at her Sentry Totem.", progress = "Ya helpin' with da frogs or not?", completion = "These be enough for me purposes. Now comes de hard part.", sourceObjectiveStatus = "unverified-source-field" }
quests[25445] = { id = 25445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zalazane's Fall", description = "De time for battle is now!  We'd be headin' ova to da islands soon, so you'd betta be ready.\n\nZalazane doesn't have much time left.", sourceObjective = "Help Vol'jin take back the Echo Isles and kill Zalazane.", completion = "{name}, you'd be a mighty warrior and a fierce commrade to da Darkspear trolls.  De Echo Isles are OURS now and we couldn'ta done it wit'out ya.\n\nTake dis cloak. Wear it wit pride.  You'd be a member of da tribe now!\n\nIn no time, da trolls will have a home again and we have you to thank for dat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25446] = { id = 25446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frogs Away!", description = "Wit de frogs ready to go, I be needin' ya to help me send 'em out to the isles.\n\nOn de eastern side of Sen'jin Village, ya can find Handler Marnlek. He be handlin' all the bats for Vol'jin's scouts and he can loan ya a bat to get ya out to de isles.\n\nTake dis sack' o frogs with ya. I been askin' de spirits for guidance. Dey've sent smoke to show ya where I need de eyes most. While ridin' de bat, reach into de sack and toss de frogs toward de white smoke.", sourceObjective = "While riding a bat, use the Sack o' Frogs to place 12 attuned frogs on the markers in the Echo Isles.", progress = "Did ya get those frogs onto de isles?", completion = "I'm already beginnin' to see what de frogs are seein'. Ya done it perfectly, {name}. Now Vol'jin and I will see what Zalazane be plannin'.", sourceObjectiveStatus = "unverified-source-field" }
quests[25447] = { id = 25447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Change", description = "A severe illness has fallen over the creatures of this forest. While at first I hoped it was part of nature's course, it has refused to pass.\n\nThe forest stags, normally strong and serene, have suffered the worst. Some waste away in weakness; others froth and rage dangerously. If I am to consult the spirits to learn more of this sickness, I will need the stags' antlers.", sourceObjective = "Collect 8 Infected Stag Antlers.", progress = "This is a sad task, {name}, but necessary.", completion = "At the very least, these creatures' suffering has ended. Let us hope their sacrifice will bring a stop to further pain.", sourceObjectiveStatus = "unverified-source-field" }
quests[25448] = { id = 25448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northspring Menace", description = "My duty here is to watch over Telaron. Even without his meditation leaving him vulnerable, there's enough threats in this forest to keep both of us on our toes.\n\nThat's why it maddens me so much that I don't have the opportunity to leave camp. More harpies than I've ever seen infest the northwest...foul creatures, spreading their filth across the ancient ruins uncaringly.\n\nThey're a threat to this camp, and have no place in these lands. I'll pay you well if you get rid of them.", sourceObjective = "Kill 6 Northspring Harpies and 6 Northspring Windcallers.", completion = "Thank you, {class}. That's one less distraction for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25449] = { id = 25449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of Quality", description = "My philosophy on leatherworking is that the work must be the best quality possible - no compromises. Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!\n\nIn my latest pursuit of high-quality materials, I have run across thick yeti hides. The Yeti are native to Feralas, with many found in Rage Scar Hold to the northeast. I want some, and I'll give you a choice of one of my leather goods for a stack of ten.  If that sounds fair, then we're in business.", sourceObjective = "Collect 10 Thick Yeti Hides.", progress = "A stack of ten thick yeti hides will net you a choice of one of my crafted items.  Because I care about quality, I am able to ensure you'll get a good item!", completion = "Did you stop and examine the texture of these hides?  Properly treated, these hides could very well be stronger than iron.  Not many people know about these hides, and that in combination with the vast treating solutions I know will allow me to potentially make items with a true mark of quality... thanks to you, of course!\n\nAnd now, please choose from what I am able to offer you for your service!", sourceObjectiveStatus = "unverified-source-field" }
quests[25450] = { id = 25450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improved Quality", description = "It's funny how things change. The northern yetis used to yield the best hides, but these...there's been a decline in quality, it seems. Maybe something nearby is making them sick.\n\nLuckily, the Feral Scar yetis to the southeast have flourished. I bet their hides are even better than they used to be!\n\nI would reward you handsomely for a stack of ten of their hides; bring them to me here, and we'll finish our business.", sourceObjective = "Collect 10 Feral Scar Yeti Hides.", progress = "These hides may not be as resilient as thorium, but they're nice and supple.", completion = "Excellent, excellent!  These are going to work out incredibly well - I can already tell that they're going to be much harder when properly cured.\n\nThanks again for your help {name}.  Here - please take one of my latest creations.", sourceObjectiveStatus = "unverified-source-field" }
quests[25451] = { id = 25451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Yeti Hide", description = "You have found a pristine yeti hide that is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar.\n\nConsidering that Pratt McGrubben at the Feathermoon Stronghold is in the market for yeti hides, this particular one may be of considerable interest to him.", sourceObjective = "Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas.", progress = "What's this, {name} - you've got something special for me?", completion = "Incredible!  You may have found the granddaddy of all yeti hides with this!\n\nYou better believe I'll pay you for it.  I normally don't pay that much for a single hide, but I'm pretty sure I can make something special from it.  Thanks for thinking of me on this, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25452] = { id = 25452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of Quality", description = "I take pride in my leather work, and I feel it shows; quality should never be compromised.  Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!\n\nIn my latest pursuit of high-quality materials, I have discovered thick yeti hides.  Yetis are native to Feralas, often found north of here in Rage Scar Hold.  I'll give you a choice of one of my leather goods for a stack of ten.  If that is agreeable to you, then we are set!", sourceObjective = "Collect 10 Thick Yeti Hides.", progress = "Were you able to get a stack of ten thick yeti hides?  My leather goods are second to none, and I'll share a sampling with you should you have the hides.", completion = "Ah, excellent!  These hides, when given a special treatment, are as resilient as iron I tell you!  It will take many tries in order to get the right mix down for the tanning, but I am confident they will bring my mark of quality to the next level.\n\nAs for you, {name}... your assistance has proven invaluable to me.  Please take your choice from these items I have crafted.", sourceObjectiveStatus = "unverified-source-field" }
quests[25453] = { id = 25453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improved Quality", description = "I'm a bit confused. The Rage Scar yeti used to be the finest source of leather in these lands... but these pelts are weak and even rotted in spots. Some sort of illness must be plaguing the creatures.\n\nI'll have to rely on a different source. The yeti of Feral Scar Vale to the south have hides nearly as strong. They are also a great deal fiercer; do not hunt them without caution, {class}.", sourceObjective = "Collect 10 Feral Scar Yeti Hides from Feral Scar Yeti.", progress = "Are the Feral Scar yeti still there? Did you get the leather?", completion = "Excellent, excellent!  These are going to work out incredibly well - I can already tell that they're going to be much harder when properly cured.\n\nThanks again for your aid, {name}.  Here - please take one of my latest creations.", sourceObjectiveStatus = "unverified-source-field" }
quests[25454] = { id = 25454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfect Yeti Hide", description = "You have found what may very well be a perfect yeti hide.  You easily note that it is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar.\n\nConsidering that Jangdor Swiftstrider at Stonemaul Hold is in the market for yeti hides, this particular one may be of considerable interest to him.", sourceObjective = "Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Stonemaul Hold in Feralas.", progress = "What's this, {name} - you've got something special for me?", completion = "This is an incredible find!  I believe this is the finest yeti hide specimen I have ever seen!\n\nIndeed, this is certainly worthy of an appropriate bounty.  I normally don't pay that much for a single hide, but I'm confident I can make something special from it.  Thanks for thinking of me on this, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25456] = { id = 25456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back in One Piece", description = "Yeah yeah, I'm sure Felora wants you back. That woman has no respect for innovation. When I told her about the modifications I was making for my Earth Elemental, she nearly threw a fit.\n\nGo tell her everything's all well and dandy. And tell her she's not getting a share of my inevitable fortune either.\n\nShe probably likes sleeping on the rock anyway.", sourceObjective = "Return to Felora Firewreath in Silver Tide Hollow.", completion = "Sam's in one piece then? And his poor assistant Felice? Good to hear.\n\nI hope that one day he'll learn to respect the elements as more than just a tool.", sourceObjectiveStatus = "unverified-source-field" }
quests[25458] = { id = 25458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Skessesh", description = "The leader of these forces must fall! The naga's offensive will be broken with no one to command them.\n\nI saw the coward retreat into one of the abandoned buildings here. Cut your way through the others and take his head! Lady Shandris will want to see it for herself.", sourceObjective = "Slay General Skessesh and take his head.", progress = "Has the general fallen?", completion = "Good riddance to foul creatures. May the naga slither back into the sea and never return.\n\nYou've proven yourself on the battlefield, {name}. I would ask more assistance of you in defending our lands here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25459] = { id = 25459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ophidophobia", description = "If there's one thing I can't stand, it's snakes. Any kind of snake - doesn't matter.\n\nWhile I was out searching for salvage, I saw a nest of sea serpents surrounding the nearby wreckage.\n\nI simply can't relax knowing that those awful creatures could slither up in here at any moment.\n\nPlease, {class}! Do something about them!", sourceObjective = "Kill 4 Brinescale Serpents at Gorrok's Lament.", progress = "You take care of those snakes for me, {class}?", completion = "Well that's a load off my mind.\n\nThank you again, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25460] = { id = 25460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earth Rises", description = "The effects of the Twilight's Hammer attack can be felt even here, this close to the world tree.\n\nAs our forests burn, the very earth turns against us in a crazed frenzy.\n\nWe can't allow the elementals to go unchecked.  Go and help our men take care of them.", sourceObjective = "Slay 8 Scalding Rock Elementals.", progress = "You've returned, {name}.", completion = "I thank you, {name}.  Your fighting prowess is admirable.  You will be crucial to putting a halt to the elemental onslaught.", sourceObjectiveStatus = "unverified-source-field" }
quests[25461] = { id = 25461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollin' For Volunteers", description = "Vol'jin has given me his war drums and put  me in charge of trainin' da new recruits here. Only problem is we be short on new recruits.\n\nSupposin' I loaned ya dis drum, would ya use it to sound de call to war on Vol'jin's behalf in Razor Hill? If ya could even inspire just a few trolls to join da cause, it would make a difference. Once ya've convinced dem to volunteer, bring dem back to me for trainin'. Go over an' talk to Handler Marnlek to de south. He can lend you a bat for de ride to Razor Hill.", sourceObjective = "Use Vol'jin's War Drums to recruit 5 Troll Citizens in Razor Hill.\n\nYou can speak to Handler Marnlek for a bat ride to Razor Hill.", progress = "We be needin' as many volunteers as we can get.", completion = "Ya found some good ones. I be trainin' them hard and we won't stop until we've driven Zalazane from our islands.", sourceObjectiveStatus = "unverified-source-field" }
quests[25462] = { id = 25462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bears Up There", description = "Do not fear the bears in this grove, {class} - I have pacified them for the moment.\n\nMy concern at present is for the welfare of the bear cubs. The fires drove the little ones up the trees, where they've gotten stuck. We've got to get those bears safely to the ground!\n\nFlying creatures frighten them, so you'll have to climb the trees yourself. Look for footholds at the trunks. Climb the trees, grab the bear cubs, and toss them - GENTLY! - onto the target here.\n\nNothing can go wrong with this plan.", sourceObjective = "Climb up trees in the Whistling Grove, grab stranded Hyjal Bear Cubs, and then hurl them at the Soft Target from the top of the tree. This is perfectly safe.", progress = "Please don't hurt the trees. Or the bears.\n\nOr yourself.", completion = "I thank you, {name}. Those little bears are shaken up but they'll survive.\n\nAt least the ones that hit the mat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25463] = { id = 25463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Silvia", description = "A Highborne mage named Estulan, estranged from his surviving brothers, has built a tower to the east where he trains young night elves in arcane magic.\n\nWere it not for Lady Tyrande's recent mercy towards his kind, his execution would be my duty under the law. He will be watched closely, but I will not deny aid to my Sentinels simply out of pride.\n\nI've sent Silvia ahead to the Tower of Estulan to begin an offensive against the ogres infesting the nearby forest. Report to her for further orders.", sourceObjective = "Report to Silvia at the Tower of Estulan.", completion = "Good to see you here. Estulan is being...difficult. We're going to have to deal with these ogres for Lady Shandris on our own until he decides to deal with us.", sourceObjectiveStatus = "unverified-source-field" }
quests[25464] = { id = 25464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Return of Baron Geddon", description = "Ragnaros is not the only powerful elemental that has re-emerged into our world.\n\nThe dreaded Baron Geddon is leading the onslaught and we must put an end to this rampage.\n\nThe Flameseer's Staff has proven powerful.  Perhaps it is powerful enough to weaken him to the point where our arch druids can bind him where he stands.\n\nGo, {name} and be careful.  Baron Geddon is a vengeful and treacherous being.", sourceObjective = "Channel the Flameseer's Staff to weaken Baron Geddon.", progress = "Is it done yet, {name}?", completion = "Well done, {name}.  We cannot afford to lose any further ground in Hyjal.\n\nBy stopping Baron Geddon we will have dealt a huge blow to the enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[25465] = { id = 25465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still With The Zapped Giants", description = "Hey pal! I'm still working on a variant of a gnomish shrinking ray, using superior GOBLIN technological advances in its construction!  In an effort to avoid inconveniences for myself such as death, I'd like for you to try it out on some of the sea giants along the coast here.  You should find miniaturization residue on them after you shrink them - bring me back some!", sourceObjective = "Use Zorbin's Ultra-Shrinker to zap Shore Striders and collect 6 Miniaturization Residues.", progress = "I had to tweak the thing to stop working on mountain giants. Even though I wasn't the one running around zapping things, those night elves beat the copper out of me after they found those guys shrunk.", completion = "Splendifimous!  Not only am I glad to see that you've returned with the residue, but also with all your major appendages intact!  That is, well, there was never any danger in using the Ultra-Shrinker, now was there!\n\nI do appreciate your effort on my behalf, {name}.  Truly, you are a friend to goblins everywhere.  Accept this as a token of my appreciation!", sourceObjectiveStatus = "unverified-source-field" }
quests[25466] = { id = 25466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even More Fuel for the Zapping", description = "If I bet against my own better judgment and stay to run an engineering shop along the Forgotten Coast, I will need to deal with these pesky elementals.  Curse the powers of elementalism unchecked, I say!\n\nFortunately for me, and now for you my hopeful agent provocateur, the elementals represent an ideal source of raw power for my Ultra-Shrinker refinement - give them the what-for I say!  When doing this though, be sure to save me the water elemental cores!", sourceObjective = "Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays.", progress = "While I could bore you with the technical details of the utility behind elemental cores, I will instead tempt you to completion of this important task by offering valuable coin and prizes for doing so.  Yon verily, are you finished?", completion = "Scrumdillyriffic!  These cores will keep me working for some time.  Add to that the benefit of there now being fewer elementals along the coast, and I might no longer cry myself to sleep at the prospect of having set up shop in perhaps the worst place imaginable!\n\nThank you, {name}, for your efforts on my behalf.  While it certainly straps me financially to do this, allow me to show you some gratitude you may understand and appreciate... loot!", sourceObjectiveStatus = "unverified-source-field" }
quests[25467] = { id = 25467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kliklak's Craw", description = "You are pleasantly surprised to find that after being mangled and masticated by a sea crab, this map is still quite legible.\n\nIt clearly indicates that a footlocker was buried in the Kelp'thar Forest behind a gigantic mollusk.\n\nA well-drawn sketch on the back of the map shows that the owner, along with his key, was eaten by an overgrown crustacean named Kliklak.", sourceObjective = "Obtain the Corroded Key from Kliklak to unlock the Half-buried Footlocker in the Kelp'thar Forest.", progress = "The footlocker's keyhole is encrusted with barnacles, but may still be operable.", completion = "The satisfying sound of a chest unlocking is followed by the sight of once-hidden treasure.", sourceObjectiveStatus = "unverified-source-field" }
quests[25468] = { id = 25468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Faerie Dragons", description = "You wouldn't know it from looking at them, but the lovely faerie dragons that inhabit this forest can be truly fearsome if trained properly. They can do amazing things to magical energy...absorb it, redirect it, even nullify it entirely.\n\nThey're nearly harmless alone, but in large numbers, they can have a stunning effect on a battle. You can find some in the fields to the northwest, but be careful, the Horde is nearby.", sourceObjective = "Use Jesana's Faerie Dragon Call to rally 10 Sprite Dragons or Sprite Darters.", completion = "Aren't they adorable? The babies are even cuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[25469] = { id = 25469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Mountain Giants", description = "The mountain giants are our most powerful allies of the forest. They're carved from the land itself.\n\nNot many of our enemies are willing to fight off a walking hillside. It only takes a few of these to turn the tide of a battle completely.\n\nThe mountain giants here have been afflicted by some illness lately, but I've seen a healthy group of them to the southwest.", sourceObjective = "Use Jesana's Giant Call to rally 5 Mountain Giants.", completion = "Excellent!\n\n{name}, you've helped bolster our forces here, and you've saved many of these forest creatures from the Horde as well. With our army now ready, Feathermoon will stand against all threats, Horde or otherwise!\n\nOn behalf of Lady Feathermoon, I'd like to award you with this weapon, fit for a Sentinel.", sourceObjectiveStatus = "unverified-source-field" }
quests[25470] = { id = 25470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Of Da Tigers", description = "Remember de frogs ya made into me eyes and ears? Well, dey've found somethin' interestin'.\n\nOn an island to de southeast, dey've spied a tiger even de other cats seem to fear. Dis tiger, I've never seen anythin' like it.\n\nIt hunts wit' da instincts of a cat, but de mind of a person. It could be a powerful spirit and a strong ally.\n\nI'll be callin' down the spirit o' the tiger upon ya. Use its gifts to locate this cat and challenge it. See if ya can win its aid in our battle for the isles.", sourceObjective = "While imbued with the Spirit of the Tiger, lure the Tiger Matriarch out of hiding and use your new abilities to best it in combat.", progress = "Did you find out anythin' about that tiger?", completion = "Vanira's frogs be tellin' de truth, den? Dis tiger be a druid and an ally? We couldn't be hopin' for a better outcome. Dis be a good omen for de coming battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[25471] = { id = 25471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Across the Great Divide", description = "We will need to press deeper into Vashj'ir if we want to uncover what the naga are doing here.\n\nGo to the Lightless Reaches, the giant chasm bordering the Kelp'thar Forest to the west.  If you look across it, you should see a cluster of plant-life surrounding the entrance to Damplight Chamber.\n\nOnce you're inside the cave, it's a bit of a ride up until you break surface, but I have friends there that should provide you a warm welcome.", sourceObjective = "Speak to Farseer Gadra in the Damplight Chamber.", completion = "Ello, mon! You look a bit more capable then most of dem coming through here.\n\nCome rest a bit. Make yaself at home.", sourceObjectiveStatus = "unverified-source-field" }
quests[25472] = { id = 25472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flameseer's Staff", description = "A powerful artifact known as the Flameseer's Staff was lost during the initial onslaught by the enemy forces.  It was an ancient bone staff that granted its wielder power over the elements of fire.\n\nIts fragments litter the area around us.  Find them and bring them to Malfurion.  Perhaps the artifact's power will still be of use.", sourceObjective = "Obtain 8 Bone Staff Fragments.", progress = "Yes, {name}?", completion = "Excellent, {name}.  This will be a great weapon against the enemy forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[25473] = { id = 25473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'Cola", description = "Sassy's been riding me to supply some Kaja'cola for the party that's being thrown in your honor later today.\n\nOops, was it supposed to be a surprise? You didn't hear it from me!\n\nAnywho, with production down these last few days, this is all that I managed to get made. Would you take it to her?", sourceObjective = "Deliver the Six-Pack of Kaja'Cola to Sassy Hardwrench at KTC Headquarters on Kezan.", progress = "<Sassy eyes the six-pack warily, as if she expects it to explode as soon as you hand it to her.>\n\nWe need more Kaja'Cola than this!\n\nI swear I'm going to fire Dampwick if I don't kill him first!", completion = "Just so you know, you'll find Kaja'Cola all over town. It's the Bilgewater Cartel's best-selling product of all time!\n\nJust remember, image is everything if we're going to get you promoted to Trade Prince! No, wait, profits are everything! Explosions are a close second! Then, image!", sourceObjectiveStatus = "unverified-source-field" }
quests[25474] = { id = 25474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More, With Eeling [DEPRICATED]", description = "Eels are among the creepiest of Azeroth's creatures.\n\nSure, there are those who pretend that they don't mind them - and others who actually claim to favor them.\n\nThey are lying.\n\nTruth be told, no one likes eels. Eels don't even like eels.\n\nAzeroth would be a better place if no one ever had to envision an eel slithering out from the murky depths and biting them.\n\nIn the face.", sourceObjective = "Kill 15 of any Eel in the Kelp Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[25475] = { id = 25475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find OOX-22/FE!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\"", sourceObjective = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-22/FE is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[25476] = { id = 25476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue OOX-22/FE!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the main road!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", sourceObjective = "Escort OOX-22/FE to safety, then report to Oglethorpe Obnoticus in Booty Bay.", completion = "Oh, YOU'RE the great savior of OOX-22/FE!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!\n\nPlease, take your choice of any of these items I have.  Thank you again for your generous assistance {name}, my robots and I are in your debt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25477] = { id = 25477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better Late Than Dead", description = "Greetings, friend.\n\nIt is good to see that you survived your battle in one piece.\n\nWhile Erunak tries to scry a place of safety for us all, I shall assist you in securing a less strenuous means of transport.\n\nI have prepared this baitstick to use near a sea turtle. It is crude, but it should serve to bring one under your control.\n\nOnce you've become comfortable with the animal, simply guide it back here to me.", sourceObjective = "Use Moanah's Baitstick on a Speckled Sea Turtle and ride it back to her.", progress = "Were you able to tame a sea turtle, {name}?", completion = "How unfortunate...\n\nWell, all things considered, it is good to see that you made it back unharmed.", sourceObjectiveStatus = "unverified-source-field" }
quests[25478] = { id = 25478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Summit", description = "We are staging a relief effort at Westreach Summit for all of Thousand Needles. The goblin, Dyslix Silvergrub, will lend you my wind rider to safely get you there. Speak with Kanati Greycloud when you land.\n\nYou must go quickly if lives are to be saved!", sourceObjective = "Borrow a wind rider from Dyslix Silvergrub and speak with Kanati Greycloud at Westreach Summit in Thousand Needles.", completion = "Nyse sent you? Good! We need your help, now!", sourceObjectiveStatus = "unverified-source-field" }
quests[25479] = { id = 25479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To New Thalanaar", description = "We are staging a relief effort at New Thalanaar for all of Thousand Needles. The goblin, Dyslix Silvergrub, will lend you my hippogryph to safely get you there. Speak with Caryssia Moonhunter when you land.\n\nYou must go quickly if lives are to be saved!", sourceObjective = "Borrow a hippogryph from Dyslix Silvergrub and speak with Caryssia Moonhunter at New Thalanaar in Feralas.", completion = "Thyssiana sent you? Good! We need your help, now!", sourceObjectiveStatus = "unverified-source-field" }
quests[25480] = { id = 25480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dance Of De Spirits", description = "De time has come to start thinkin' about when to make our move. Champion Uru'zin tells me his men be ready. You and Vanira done good work gatherin' information on de enemy and findin' us new allies.\n\nNow, we read de omens. We find out when to launch de attack.\n\nFind Witch Doctor Hez'tok near the circle of ritual dancers. He be startin' de ritual as soon as ya be ready.", sourceObjective = "Talk to Witch Doctor Hez'tok near the circle of ritual dancers outside Sen'jin Village when you're ready to consult the omens.", progress = "Well, what do de omens tell us?", completion = "I will take de spirits' advice to heart. Wit' dem behind us and de power of de ancient loas of de Darkspear Tribe, we be ready to reclaim what's ours!", sourceObjectiveStatus = "unverified-source-field" }
quests[25481] = { id = 25481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To New Thalanaar", description = "We are staging a relief effort at New Thalanaar for all of Thousand Needles. Seyala Nightwisp will lend you my hippogryph to safely get you there. Speak with Caryssia Moonhunter when you land.\n\nYou must go quickly if lives are to be saved!", sourceObjective = "Borrow a hippogryph from Seyala Nightwisp and speak with Caryssia Moonhunter at New Thalanaar in Feralas.", completion = "Falfindel Waywarder sent you? Good! We need your help, now!", sourceObjectiveStatus = "unverified-source-field" }
quests[25482] = { id = 25482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Headless Horseman" }
quests[25483] = { id = 25483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Coren Direbrew" }
quests[25484] = { id = 25484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Ahune" }
quests[25485] = { id = 25485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Hummel" }
quests[25486] = { id = 25486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem are Coming", description = "This is going to take a while, but I'm sure we'll beat them back.\n\nYou're more good to Thousand Needles elsewhere. We have reports that the gnomes and goblins out on the flooded salt flats somehow survived on a giant barge! Rendow is on the dock. She'll get you a boat to go there.\n\nMind helping us out a little on your way to her?", sourceObjective = "Slay 7 Grimtotem Marauders.", progress = "Think you could take care of a few more of the Grimtotem for us first, friend?", completion = "A boat? Yes, you can have this last one.", sourceObjectiveStatus = "unverified-source-field" }
quests[25487] = { id = 25487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem are Coming", description = "The cowardly Grimtotem have attacked us by surprise when we were least prepared!\n\nYou will be of most help to Thousand Needles elsewhere, {class}. We have heard rumors that the goblins and gnomes somehow survived in a giant barge out on the salt flats.\n\nMotega Firemane is at the base of the summit. He can get you a canoe to take you there.\n\nDo you mind helping us fight off the Grimtotem on your way to him?", sourceObjective = "Slay 7 Grimtotem Pillagers.", completion = "You want a canoe to go out to the salt flats? But, surely the race track has been destroyed?!\n\nNonetheless, for your bravery, you will have the last one!", sourceObjectiveStatus = "unverified-source-field" }
quests[25488] = { id = 25488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two If By Boat", description = "Are you ready to go, {class}? One of the sentinels will take you out to the Mirage Raceway.\n\nIf there's anyone left alive out there, please help them.\n\nGoddess watch over you!", sourceObjective = "Speak with Fizzle Brassbolts at Fizzle & Pozzik's Speedbarge in Thousand Needles.", completion = "YES?! Do you see me interrupting your fascinating argument?\n\nNo... no, please, go ahead. I'm sure that your interruption is about something very important. More important than dealing with the survival of everyone here, in fact.\n\n<Fizzle taps his foot impatiently.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25489] = { id = 25489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two If By Boat", description = "Are you ready to go, {class}?\n\nOne of our braves will row you out to the Mirage Raceway. If anyone has survived out there, they'll desperately need your help.\n\nMay the Earth Mother smile upon you.", sourceObjective = "Speak with Pozzik at Fizzle & Pozzik's Speedbarge in Thousand Needles.", completion = "Heya, kid, I'll be right with ya. Just gotta shut this gnome twerp up first.", sourceObjectiveStatus = "unverified-source-field" }
quests[25490] = { id = 25490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smashing Through Ashes", description = "{name}, these fiends from the Twilight's Hammer are attempting to scourge this whole mountain clean of all life. Even now they trail behind this inferno, leaving death and ash in their wake.\n\nArch Druid Hamuul Runetotem is behind the fires, trying to salvage the wilderness before it's blotted permanently from the map. Travel southeast, through The Inferno and down the road beyond. Find and aid the Arch Druid.\n\nOn your way there, clear the roads by killing any Charbringers that you find.", sourceObjective = "Slay 8 Charbringers.", completion = "Very good. The Twilight's Hammer must be sent the message that we will never give up.", sourceObjectiveStatus = "unverified-source-field" }
quests[25491] = { id = 25491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durable Seeds", description = "This land has been scourged by fire, but it may yet renew itself.\n\nSome seeds deep in the soil may have withstood the scorching heat here in The Flamewake. These durable plants are the key to this forest's regrowth. Please, collect some of these seedlings for me.", sourceObjective = "Gather 10 Hyjal Seedlings from piles of Scorched Soil.", progress = "I suspect life still struggles beneath the ash. What were you able to find?", completion = "<The Arch Druid inspects the seedlings.>\n\nThese seedlings have survived an apocalypse. Even a handful hold great power. Life always replenishes itself, often stronger than before.\n\nOnce the way is clear, we will use these to perform a miracle on this mountain, {name}. You will see.", sourceObjectiveStatus = "unverified-source-field" }
quests[25492] = { id = 25492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebreak", description = "In their efforts to decimate Hyjal, Twilight's Hammer has elementals scouring the earth in the wake of the fire.\n\nThey're pulverizing the soil, rooting around in the ash, digging up any scrap of plantlife that survived and destroying it. It's like they're paving the way for... I don't even want to imagine.\n\nStop them before Hyjal is devoid of life. Kill the lava surgers!", sourceObjective = "Slay 10 Lava Surgers.", progress = "If Hyjal is any indication of their plans for the rest of Azeroth, I shudder to think of what will happen if Twilight's Hammer ever gets their way.", completion = "Good work, {name}. There's a chance the forest will recover from this yet.\n\nNow, there's something else I need you to take care of for me...", sourceObjectiveStatus = "unverified-source-field" }
quests[25493] = { id = 25493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Bait", description = "I was stunned to discover that Twilight's Hammer had located - and imprisoned - the great turtle ancient Tortolla. As we speak he is chained above the murky waters of the Ashen Lake.\n\nFreeing Tortolla from his bonds will not be easy. But we will take it one step at a time.\n\nHead into the Flamewake and collect for me heaps of core hound entrails. I will explain why later.\n\nAnd beware of Nemesis the Usurper while you are there! His time will come, but we are not yet prepared.", sourceObjective = "Collect 4 heaps of Core Hound Entrails.", progress = "Have you collected the innards?\n\nCore hounds are not native to this part of the world, they accompanied Twilight's Hammer from the nether regions of the earth. Do not trouble yourself over their elimination.", completion = "Very good. We will need these to act as bait while they are still warm.\n\nHere is my plan...", sourceObjectiveStatus = "unverified-source-field" }
quests[25494] = { id = 25494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion's Collar", description = "This little guy is a true menace now, isn't he?\n\nWe're going to have to give him a nice spiked collar if he's going to be a fighting pup.\n\nThe basilisk matriarch has made her lair off of the road to Winterspring.  Bring me her spiked hide and we'll fashion a collar for our little killer here.", sourceObjective = "Obtain the Spiked Basilisk Hide from the Spinescale Matriarch.", progress = "Did you get it?", completion = "Excellent!  Our pup is ready for a fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[25495] = { id = 25495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparin' For Battle", description = "Vol'jin be gatherin' his gear and readyin' de warriors. He ask me to tell ya to meet with him an' Vanira on de island to de east.\n\nFrom dere, he and de warriors will launch de attack on Zalazane. May de ancestors go wit' you, {name}. Without ya, dis campaign would only be a shadow of what it become. Speak to Handler Marnlek, just to de south, an' he give you a bat to fly out to de stagin' area.", sourceObjective = "Speak to Handler Marnlek for a flight to the staging area. Meet Vol'jin on the island east of the war camp.", completion = "At last, everythin' be ready. Now, we show Zalazane what happen to dose who defy de Darkspears!", sourceObjectiveStatus = "unverified-source-field" }
quests[25496] = { id = 25496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grudge Match", description = "I don't know if you've picked up on this, but there's a bit of a rivalry between the ogre members of the Twilight's Hammer and the rest of us.\n\nFor me... it's personal.\n\nThis one ogre called Gromm'ko has a pet raptor named \"Butcher.\"  He's taken out the last three of my corehound pups.\n\nI think this last one will fare differently.  He's got a real killer's instinct.\n\nGo to the Seat of the Chosen and challenge Gromm'ko to a match between our two beasts.  Humiliate him for me, {name}damus.", sourceObjective = "Challenge Gromm'ko at the Seat of the Chosen in Hyjal.", progress = "Is it done, Thorbknightdamus?  Did our little champ make it out ok?", completion = "That's how it's done!", sourceObjectiveStatus = "unverified-source-field" }
quests[25497] = { id = 25497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back in the Saddle", description = "Our situation is growing a bit desperate, r.\n\nWe must focus our attention on the naga and their prisoners, but it would be folly to do so without being prepared, and down here that means finding a way to travel more quickly.\n\nThese sharks are clearly fond of sea turtle. Let's see if we can turn that into our advantage.", sourceObjective = "Use 6 Turtle Meat to create shark bait.", sourceObjectiveStatus = "unverified-source-field" }
quests[25499] = { id = 25499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agility Training: Run Like Hell!", description = "Before we go any further, we're going to have to get you into shape.\n\nDevotion to the Old Gods is not going to save you when some emerald dragon comes chasing after you.  You need to be fleet of foot, if you catch my drift.\n\nEnough said.  We'll summon your trainer... your job is to run away from him without leaving this camp.\n\nGo!", sourceObjective = "Run away from the Blazing Trainer within the Forge of Supplication for 1 minute.", progress = "Yes?", completion = "Oh.  You're still alive.\n\nNot bad.", sourceObjectiveStatus = "unverified-source-field" }
quests[25500] = { id = 25500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words for Delivery", description = "Here we go.  This is the speech, {name}!\n\nIt has everything to be a great battle starter: It's inspirational, has eloquent language and speaks directly to gnomes.  Never has a finer speech been written!\n\nTurn this in to Captain Tread Sparknozzle and see if there's anything else he needs of you.", sourceObjective = "Give the speech to Captain Tread Sparknozzle at Steelgrill Depot.", progress = "What do you have there, recruit?", completion = "This is the speech from Toby?  Fantastic!\n\nRecruit, you've done all we could possibly ask for and the Gnomeregan Army thanks you!\n\nWe've got a strike team heading to Gnomeregan now and that wouldn't have been possible without your assistance.  For all of your help, we'd like you to join the Gnomeregan Reserves!\n\nIt doesn't pay very well, but you do get this snazzy helmet.  Hang on to that, you might need it someday!", sourceObjectiveStatus = "unverified-source-field" }
quests[25502] = { id = 25502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepping the Soil", description = "The Arch Druid has tasked me with setting up a series of flamewards around the perimeter of the area. Once these are active, we can prevent further attacks from the fire elementals that left this valley in ruins.\n\nThese will also protect and nourish the soil for whatever Hamuul has planned.\n\nIt's time to begin. Find one of the five flamewards I've marked on your map, activate it, and defend it from counterattack until its magic kicks in. It won't take more than a minute.", sourceObjective = "Activate and defend a Flameward.", completion = "That's good! Between your work and the work of a few others, that valley is secure from a counter-attack.\n\nI've done all I can. It's all up to you and the Arch Druid now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25503] = { id = 25503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfin's Booty", description = "<A torn page precedes the latest entry, which reads:>\n\nOur self-proclaimed king will stop at nothing to acquire my family fortune. He has threatened and harassed me to no end.\n\nI can't take it anymore!\n\nI've buried the treasure and fed the map to Blackfin.\n\nThat should keep my cousin's grubby little mitts off of our precious heirlooms!", sourceObjective = "You must slay the orca, Blackfin, to retrieve Gilblingle's Map.", progress = "You've discovered Gilblingle's family treasure!", completion = "This item was highly prized by the local gilblin population - even coveted by King Gurboggle, himself!", sourceObjectiveStatus = "unverified-source-field" }
quests[25504] = { id = 25504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Me a Favor?", description = "Hello there. Pleased to meet you! I'm Fizzle Brassbolts. Welcome to my Speedbarge.\n\nI share your concerns about helping all of Thousand Needles. It's my firm belief that the Speedbarge is the best hope for the entire region.\n\nPerhaps you could help us out a little bit here? I'll make sure that you're equipped with what you need to tackle everything else.\n\nAs to that, if you could just run this list of parts over to Jinky Twizzlefixxit in her shop, you'll be well on your way.", sourceObjective = "Deliver the List of Parts to Jinky Twizzlefixxit at Fizzle & Pozzik's Speedbarge in Thousand Needles.", progress = "Is that the list of parts, finally? I've been waiting all day for that!", completion = "<Jinky eyes the list of parts and spits!>\n\nI don't have even half of that stuff!", sourceObjectiveStatus = "unverified-source-field" }
quests[25505] = { id = 25505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Me a Favor?", description = "Hey there, {name}. I'm Pozzik, world-renowned rocket car pilot. Welcome to my Speedbarge.\n\nI share your concerns about helping all of Thousand Needles. It's my firm belief that the Speedbarge is the best hope for the entire region.\n\nPerhaps you could help us out a little bit here? I'll make sure that you're equipped with what you need to tackle everything else.\n\nAs to that, if you could just run this list of parts over to Razzeric in his shop, you'll be well on your way.", sourceObjective = "Deliver the List of Parts to Razzeric at Fizzle & Pozzik's Speedbarge in Thousand Needles.", progress = "Is that my list of parts from Pozzik?", completion = "Heya, pal, mind if I take a look at that list?\n\n<Razzeric nearly spits!>\n\nWhat's Pozzik thinking? He knows that I don't have even half of that stuff!", sourceObjectiveStatus = "unverified-source-field" }
quests[25506] = { id = 25506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea-Food Chain", description = "Our time here draws to a close.\n\nI must find my way across the chasm and discover the purpose behind the naga activities here.\n\nIf you are to follow me, you would be wise to conclude your search for a suitable mount first.\n\nSearch the area north of here and find a puffer hatchling. Once you've caught one, bring it to the trench to the west. I will prepare everything you need there.", sourceObjective = "Find a Puffer Hatchling in Gnaws' Boneyard and bring it to the Abyss near the Holding Pens.", sourceObjectiveStatus = "unverified-source-field" }
quests[25507] = { id = 25507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hell's Shells", description = "Fresh and stinking, these innards will prove to be irresistible for Nemesis, the befouled turtle god created by Twilight's Hammer.\n\nNemesis must eventually be destroyed, but first, we must collect a piece of his fiery armored shell. With it, we'll be able to work some magic to free the true ancient.\n\nGo into the Flamewake and drop this bait near Nemesis. It will distract him. Pry off a piece of his shell... then run, if you hope to survive the encounter.", sourceObjective = "Use the Heap of Core Hound Innards near Nemesis to distract him. Collect a Nemesis Shell Fragment.", progress = "Nemesis is a molten ball of fury protected by a stony shell of pure hatred.\n\nHis time will come.", completion = "<The Arch Druid takes the shell from you with surprising reverence.>\n\nNemesis is an instrument of evil, but he was forged from a shell fragment of the true ancient.\n\nWe will exploit this connection.", sourceObjectiveStatus = "unverified-source-field" }
quests[25509] = { id = 25509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Physical Training: Forced Labor", description = "Training to join our ranks is not pleasant.  Why should it be?\n\nThe path to serve the Old Gods is long, painful, and soul-harrowing.  Consider this your first step.\n\nTake this pick and break the lodestone deposits found in the gorge.\n\nNo, we don't need any of the ore.  This is purely for your benefit.", sourceObjective = "Break 5 Darkwhisper Lodestones.", completion = "Very well.  You're at least competent enough to figure out which way the pointy end of the pick goes.", sourceObjectiveStatus = "unverified-source-field" }
quests[25510] = { id = 25510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortolla Speaks", description = "<The Arch Druid fills the shell fragment with water, which boils instantly. He adds a bundle of herbs and closes his eyes in a silent prayer.>\n\n{name}, Tortolla the turtle ancient is ageless, a part of this world since the time of the titans. He speaks a language older than our understanding.\n\nDrink this and find a place of calm within yourself. You will be able to understand the language of Tortolla. Go to him now, in the Ashen Lake. Earn the ancient's trust. The fate of Hyjal hinges on this.", sourceObjective = "Go to Tortolla, the turtle ancient, at the Ashen Lake in Mount Hyjal.", completion = "{race}.\n\nThis tongue. Is not yours.\n\nWhat do you want ... tormentor?", sourceObjectiveStatus = "unverified-source-field" }
quests[25513] = { id = 25513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderdrome: Grudge Match!", description = "It seems we have a special request! I have here a note from one Kelsey Steelspark, requesting to enter the cage and settle a dispute.\n\nShe's asked for you to be her partner, {name}. A fan of your previous victories? Or perhaps you're acquainted outside the ring?\n\nI wouldn't back down now if I were you. This is the grand finale...", sourceObjective = "Defeat Megs Dreadshredder.", completion = "Fantastic. I might challenge you to a duel myself someday.", sourceObjectiveStatus = "unverified-source-field" }
quests[25514] = { id = 25514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Bonds", description = "From the deep...\nA realm of darkness and fire.\nGrasping in my slumber.\n\nI am ensnared, {race}.\n\nShadows lurk in the rods of fire beside me.\nSlay them.\nThat I may be free again.", sourceObjective = "Disable the two Rods of Subjugation that bind Tortolla.", progress = "They are not of this world.\n\nThey know neither pity nor fear.", completion = "<Tortolla quivers and shakes debris free from his great back.>\n\nYou...\nAre not like the others.\n\nI am free once again.\n\nThe others...\nWill pay.", sourceObjectiveStatus = "unverified-source-field" }
quests[25515] = { id = 25515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down in the Deeps", description = "<Jinky rolls up her sleeves and slicks back her hair while eyeing you up and down.>\n\nFine, if Fizzle wants you to have your own boat, the first thing we'll need is parts. Guess who gets to go get them?\n\n<Jinky smiles as she points downward and then grabs you a spare diving helm and flippers.>\n\nThat's right, <brother/sister>. You get to go down into the deeps and salvage what rocket car parts you can find at the Raceway Ruins.", sourceObjective = "Collect 10 Rocket Car Parts.", progress = "I'm not punching the timecard on this one until you get me everything that's on that parts list.", completion = "This'll do for a start.", sourceObjectiveStatus = "unverified-source-field" }
quests[25516] = { id = 25516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down in the Deeps", description = "Well, friend, if Pozzik wants you to have your own boat, the first thing we're going to need is parts. Now guess who gets to go get them?\n\n<Razzeric smiles as he points downward and then grabs you a spare diving helm and flippers.>\n\nI'm afraid so, {name}. You get to go down into the deeps and salvage what rocket car parts you can find at the Raceway Ruins.", sourceObjective = "Collect 10 Rocket Car Parts.", progress = "We can get started as soon as you get everything that's on the list.", completion = "This is a great start!", sourceObjectiveStatus = "unverified-source-field" }
quests[25517] = { id = 25517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Fight!", description = "Those no-good, smelly, green in the gills goblins have got it coming!\n\nI want you to go into the Speedbarge Bar, order a bottle of grog, and hit one over the head with it!\n\nShow them that we're not going to take any more of their insolence, {name}!", sourceObjective = "Start a bar fight!", progress = "What? Are you deaf?\n\nYou need to go start that bar fight... now!", completion = "That's the spirit! You're a real credit to the Alliance!\n\nYou know, you can go back in there and do that anytime you feel like it. I highly encourage you to do so!", sourceObjectiveStatus = "unverified-source-field" }
quests[25518] = { id = 25518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Fight!", description = "Those pint-sized, goober-looking, no-explosion gnomes have got it coming!\n\nI want you to go into the Speedbarge Bar, order a bottle of grog, and hit one over the head with it!\n\nShow them that we're not going to take any more of their arrogance, {name}!", sourceObjective = "Start a bar fight!", progress = "What? Are you deaf?\n\nYou need to go start that bar fight... now!", completion = "Yes! You're a real credit to the Horde!\n\nYou know, you can go back in there and do that anytime you feel like it. I highly encourage you to do so!", sourceObjectiveStatus = "unverified-source-field" }
quests[25519] = { id = 25519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children of Tortolla", description = "My children.\nThey lie below.\nIn silt and sand.\n\nThe others corrupt them.\nDarken them within their shells.\n\nSlay the others.\nDestroy the corruptors.\nSave them...", sourceObjective = "Slay 6 Deep Corruptors attacking Tortolla's Eggs in the Ashen Lake.", progress = "My children.\nTell me they will be born free...", completion = "{race}.\nYou are not like the others.\n\nBraver. Stronger.\nA part of this world...\n    and not the shadow that came before.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25520] = { id = 25520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Awakens", description = "I slumbered in the healing silt of Hyjal.\nI slept until the world broke open.\nWhen the others came, I was not ready.\n\nI am ready now, {race}.\n\nMy children and I. Slow to anger.\nBut our wrath is final.\n\nTell those who sent you that we are prepared for war.\n\nThe others will be cast from the mountain.", sourceObjective = "Return to Arch Druid Hamuul Runetotem at the Sanctuary of Malorne in Hyjal.", completion = "{name}!\n\nYou were able to earn the ancient's trust?\n\nWonderful! We are one step closer to taking back this mountain...", sourceObjectiveStatus = "unverified-source-field" }
quests[25521] = { id = 25521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm With Scorpid", description = "You gotta help me, you just gotta! Chelsea and I came out here to make a bit of money, just sell some supplies, legit work. Next thing I know she's on her deathbed! She's got a fever that'd shock a blacksmith, and she's hallucinating...\n\nShe must've been stung by the scorpids near here! I've seen it happen, it's not pretty. I gotta get some poison glands to make an antidote but I can't leave her side!\n\nPlease, help me! Get me those glands!", sourceObjective = "Collect 6 Duneclaw Stingers from Duneclaw Scorpids.", progress = "Do you have them? Oh, please...", completion = "Oh thank you, thank you! I know a bit of alchemy, I'm not totally useless. Here goes...", sourceObjectiveStatus = "unverified-source-field" }
quests[25522] = { id = 25522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargantapid", description = "No! It didn't work! I don't know what to do, unless...\n\nOh gosh, it's worse than I thought! She must've been stung by the one lurking in the cave. I saw it the first night we arrived. Claws the size of a goblin. A tail as tall as a tree! We shared hushed whispers of it around the campfire... we called it... GARGANTAPID!\n\n ...hey, are you laughing? Stop that! This is serious! Chelsea's life is on the line! Please, I'll make it worth your while...just bring me Gargantapid's poison gland!", sourceObjective = "Collect Gargantapid's Stinger.", progress = "You're back! Do you have it?", completion = "I can't believe it! You're amazing! Here, please, take your reward, take anything you want! I've gotta save Chelsea!", sourceObjectiveStatus = "unverified-source-field" }
quests[25523] = { id = 25523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight in the Firelands", description = "{name}, our enemy is using this grotto in the Firelands to prepare an invasion. We're going to hit them hard right where they live.\n\nBut first, you'll need to get your wings. Flight in the Firelands does not work as it does in the outside world. Something about the dense, superheated air. You'll need some practice!\n\nGet a Twilight Firelance from the rack behind me, equip it, then mount one of Aviana's Guardians. Practice flying - flap your wings! Visit a flag placed on the ledge below and return.", sourceObjective = "Get and equip a Twilight Firelance using the rack behind Farden. Mount one of Aviana's Guardians and fly her to the Guardian Flag on the ledge below. Press the flap button to flap your mount's wings!", progress = "Do you feel comfortable flying yet?", completion = "Well done! How does it feel?\n\nIt is challenging to master flight in this burning wasteland, but it is the only way.\n\nI hope you're ready for battle, {name}...", sourceObjectiveStatus = "unverified-source-field" }
quests[25524] = { id = 25524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Outhouse", description = "Hello? Hello! HELP!\n\nI'm almost out of air! You have to get me out of here!\n\n<The voice inside gags.>\n\nOne of those Southsea treasure hunters has got to have a crowbar!", sourceObjective = "Obtain a Pirate's Crowbar and use it to pry open the Submerged Outhouse door.", progress = "Oh, for the love of the Light, do you have that crowbar yet? Drowning here!", completion = "Thank goodness! Now, just a little shove....", sourceObjectiveStatus = "unverified-source-field" }
quests[25525] = { id = 25525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wave One", description = "Here they come, {name}! The Twilight Knight Riders, astride black buzzards birthed in the scorching sulfurous breeding pools of the Firelands. The only way to defeat them is from the sky!\n\nTake wing once more, {class}, and slay them.\n\nRun into enemy riders with your lance to destroy them.\n\nGo forth. Fly, fool. Fly!", sourceObjective = "Equip a Twilight Firelance and fly Aviana's Guardian. Kill 10 Twilight Knight Riders by flying into them. Press the flap button to flap your mount's wings!", progress = "Flap! Flap I say... FLAP!", completion = "Spectacular flying, {name}! Their screeches of anguish echoed about this light-forsaken cavern.\n\nBut our work is not yet finished...", sourceObjectiveStatus = "unverified-source-field" }
